def save_alpaca_managed_buy_order(conn: sqlite3.Connection, **kwargs: object) -> int:
    """Create modern managed-buy fixtures with immutable submission intent."""
    kwargs.setdefault("buy_order_qty", 2)
    kwargs.setdefault("buy_order_limit_price", 105)
    position_id = _save_alpaca_managed_buy_order(conn, **kwargs)
    if submitted_at := kwargs.get("buy_submitted_at"):
        conn.execute(
            "UPDATE alpaca_managed_positions SET created_at = ? WHERE id = ?",
            (submitted_at, position_id),
        )
        conn.commit()
    return position_id


def submit_alpaca_paper_buy_orders(
    buy_signals: pd.DataFrame,
    cfg: AlpacaOrderConfig,
    conn: sqlite3.Connection | None = None,
) -> pd.DataFrame:
    """Give ordinary live-buy fixtures the required fresh observation date."""
    buy_signals = buy_signals.copy()
    if not buy_signals.empty and "RSI Observation Date" not in buy_signals:
        buy_signals["RSI Observation Date"] = buy_signals["Date"]
    with patch(
        "leveraged_trader.alpaca._market_clock_now",
        return_value=datetime(2026, 1, 5, 13, 30, tzinfo=UTC),
    ):
        return _submit_alpaca_paper_buy_orders(buy_signals, cfg, conn)


def _complete_order_fixture(payload: object) -> object:
    """Give ordinary broker fixtures the complete shape returned by Alpaca."""
    if isinstance(payload, list):
        return [_complete_order_fixture(item) for item in payload]
    if not isinstance(payload, dict):
        return payload

    if "id" not in payload:
        return payload

    order = dict(payload)
    identifier = str(order.get("id", ""))
    client_order_id = str(order.get("client_order_id", ""))
    side = str(order.get("side", "")).lower()
    if not side:
        side = "sell" if "sell" in identifier or "exit" in client_order_id else "buy"
    symbol = str(order.get("symbol") or ("SATG" if "SATG" in client_order_id else "TQQQ"))
    order.setdefault("client_order_id", f"rsi-{'exit' if side == 'sell' else 'buy'}-{symbol}-1")
    if side == "buy" and order["client_order_id"].endswith("-1"):
        order["client_order_id"] = f"rsi-buy-{symbol}-20260102"
    order.setdefault("asset_id", f"asset-{symbol.lower()}")
    order.setdefault("symbol", symbol)
    order.setdefault("asset_class", "us_equity")
    order.setdefault("side", side)
    order.setdefault("type", "limit")
    order.setdefault("time_in_force", "gtc" if side == "sell" else "day")
    order.setdefault("extended_hours", False)
    order.setdefault("status", "accepted")
    order.setdefault("qty", "2")
    order.setdefault("filled_qty", "0")
    order.setdefault("limit_price", "150" if side == "sell" else "105")
    order.setdefault(
        "submitted_at",
        "2026-01-02T14:32:00Z" if side == "sell" else "2026-01-02T14:30:00Z",
    )
    order.setdefault("updated_at", order["submitted_at"])
    return order


def _complete_asset_class_fixture(payload: object) -> object:
    """Give ordinary position and simple-order fixtures required account metadata."""
    if isinstance(payload, list):
        return [_complete_asset_class_fixture(item) for item in payload]
    if not isinstance(payload, dict) or payload.get("order_class") == "mleg":
        return payload
    if "asset_id" not in payload or "symbol" not in payload:
        return payload
    enriched = dict(payload)
    enriched.setdefault("asset_class", "us_equity")
    # Alpaca Position objects have no order ``id`` and require an explicit
    # long/short side. Keep this coupled to ``complete_asset_classes`` so tests
    # can still opt out when exercising any malformed position metadata.
    if "id" not in enriched and "qty" in enriched:
        enriched.setdefault("side", "long")
    return enriched


