    def test_reconciliation_uses_one_account_order_snapshot_for_multiple_tracked_sells(self) -> None:
        cfg = self.cfg(buy=True, sell=True)
        client = Mock()
        client.cfg = cfg
        orders: list[dict] = []

        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            for index, symbol in enumerate(("TQQQ", "UPRO"), start=1):
                position_id = save_alpaca_managed_buy_order(
                    conn,
                    symbol=symbol,
                    alpaca_asset_id=f"asset-{symbol.lower()}",
                    signal_symbol="QQQ" if symbol == "TQQQ" else "SPY",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id=f"rsi-buy-{symbol}-20260102",
                    buy_alpaca_order_id=f"buy-{index}",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="filled",
                )
                mark_alpaca_managed_buy_filled(
                    conn,
                    position_id,
                    buy_status="filled",
                    filled_qty=2,
                    filled_avg_price=100,
                    filled_at="2026-01-02T14:31:00Z",
                    target_sell_price=150,
                )
                sell_client_order_id = f"rsi-exit-{symbol}-{position_id}"
                sell_order_id = f"sell-{index}"
                record_alpaca_managed_sell_order(
                    conn,
                    position_id,
                    sell_client_order_id=sell_client_order_id,
                    sell_alpaca_order_id=sell_order_id,
                    sell_submitted_at="2026-01-02T14:32:00Z",
                    sell_status="new",
                    sell_order_qty=2,
                    sell_order_limit_price=150,
                )
                orders.append(
                    _complete_order_fixture(
                        {
                            "id": sell_order_id,
                            "client_order_id": sell_client_order_id,
                            "asset_id": f"asset-{symbol.lower()}",
                            "symbol": symbol,
                            "side": "sell",
                            "status": "new",
                            "qty": "2",
                            "filled_qty": "0",
                            "limit_price": "150",
                            "expires_at": "2027-01-02T20:00:00Z",
                        }
                    )
                )

            client.all_orders.return_value = orders
            client.positions.return_value = [
                {
                    "asset_id": f"asset-{symbol.lower()}",
                    "asset_class": "us_equity",
                    "symbol": symbol,
                    "side": "long",
                    "qty": "2",
                }
                for symbol in ("TQQQ", "UPRO")
            ]
            with patch("leveraged_trader.alpaca.AlpacaClient", return_value=client):
                result = reconcile_alpaca_managed_positions(conn, cfg)

        self.assertEqual(result["Status"].tolist(), ["new", "new"])
        client.all_orders.assert_called_once_with()
        client.open_orders.assert_not_called()
        client.get_order.assert_not_called()
        client.get_order_by_client_order_id.assert_not_called()

    def test_closed_audits_share_one_account_order_snapshot(self) -> None:
        cfg = self.cfg(buy=True, sell=True)
        client = Mock()
        client.cfg = cfg
        audited_position_ids: list[int] = []

        def observe_snapshot(*, client: Mock, position: dict, **_kwargs: object) -> None:
            cached = vars(client).get("_reconciliation_order_payloads")
            self.assertIsInstance(cached, dict)
            self.assertIn(position["buy_alpaca_order_id"], cached)
            self.assertIn(position["sell_alpaca_order_id"], cached)
            audited_position_ids.append(int(position["id"]))

        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            first = save_closed_balanced_managed_position(conn)
            second = save_closed_balanced_managed_position(
                conn,
                symbol="UPRO",
                signal_symbol="SPY",
            )
            order_ids = {
                str(position[field])
                for position in (first, second)
                for field in ("buy_alpaca_order_id", "sell_alpaca_order_id")
            }
            client.all_orders.return_value = [{"id": order_id} for order_id in sorted(order_ids)]
            with (
                patch("leveraged_trader.alpaca.AlpacaClient", return_value=client),
                patch(
                    "leveraged_trader.alpaca._audit_recently_closed_managed_position",
                    side_effect=observe_snapshot,
                ),
            ):
                result = reconcile_alpaca_managed_positions(conn, cfg)

        self.assertTrue(result.empty)
        self.assertEqual(audited_position_ids, [int(first["id"]), int(second["id"])])
        client.all_orders.assert_called_once_with()
        client.open_orders.assert_not_called()
        client.get_order.assert_not_called()

    def test_managed_order_identity_rejects_advanced_classes_and_companion_legs(self) -> None:
        simple_order = _complete_order_fixture(
            {
                "id": "sell-1",
                "client_order_id": "rsi-exit-TQQQ-1",
                "asset_id": "asset-tqqq",
                "symbol": "TQQQ",
                "side": "sell",
                "status": "accepted",
                "qty": "2",
                "limit_price": "150",
            }
        )

        def matches(order: dict) -> bool:
            return _order_matches_core_intent(
                order,
                expected_symbol="TQQQ",
                expected_alpaca_asset_id="asset-tqqq",
                expected_side="sell",
                expected_order_type="limit",
                expected_time_in_force="gtc",
                require_complete=True,
            )

        self.assertTrue(matches(simple_order))
        self.assertTrue(matches({**simple_order, "order_class": "simple", "legs": []}))
        for asset_class in (None, "global_equity"):
            with self.subTest(asset_class=asset_class):
                wrong_asset_class = dict(simple_order)
                if asset_class is None:
                    wrong_asset_class.pop("asset_class")
                else:
                    wrong_asset_class["asset_class"] = asset_class
                self.assertFalse(matches(wrong_asset_class))
                self.assertEqual(
                    _matching_managed_open_sell_orders(
                        [wrong_asset_class],
                        "TQQQ",
                        1,
                        expected_alpaca_asset_id="asset-tqqq",
                    ),
                    [],
                )
        for order_class in ("bracket", "oco", "oto"):
            with self.subTest(order_class=order_class):
                advanced_order = {**simple_order, "order_class": order_class}
                self.assertFalse(matches(advanced_order))
                self.assertEqual(
                    _matching_managed_open_sell_orders(
                        [advanced_order],
                        "TQQQ",
                        1,
                        expected_alpaca_asset_id="asset-tqqq",
                    ),
                    [],
                )
        for malformed_order_class in (1, [], {}):
            with self.subTest(order_class=malformed_order_class):
                malformed_order = {**simple_order, "order_class": malformed_order_class}
                self.assertFalse(matches(malformed_order))
                self.assertEqual(
                    _matching_managed_open_sell_orders(
                        [malformed_order],
                        "TQQQ",
                        1,
                        expected_alpaca_asset_id="asset-tqqq",
                    ),
                    [],
                )
        companion_order = {**simple_order, "legs": [{"id": "companion-leg"}]}
        self.assertFalse(matches(companion_order))
        self.assertEqual(
            _matching_managed_open_sell_orders(
                [companion_order],
                "TQQQ",
                1,
                expected_alpaca_asset_id="asset-tqqq",
            ),
            [],
        )

    def test_managed_sell_attribution_separates_position_intent_from_adoption(self) -> None:
        sell_order = _complete_order_fixture(
            {
                "id": "sell-1",
                "client_order_id": "rsi-exit-TQQQ-1",
                "asset_id": "asset-tqqq",
                "symbol": "TQQQ",
                "side": "sell",
                "status": "accepted",
                "qty": "2",
                "limit_price": "150",
            }
        )

        compatible_orders = [
            sell_order,
            {**sell_order, "position_intent": None},
            {**sell_order, "position_intent": "sell_to_close"},
        ]
        for order in compatible_orders:
            with self.subTest(position_intent=order.get("position_intent", "<omitted>")):
                self.assertTrue(
                    _sell_order_identity_is_consistent(
                        order,
                        expected_sell_client_order_id="rsi-exit-TQQQ-1",
                        expected_symbol="TQQQ",
                        expected_alpaca_asset_id="asset-tqqq",
                    )
                )
                self.assertTrue(
                    _sell_order_matches_submission_intent(
                        order,
                        requested_qty=2,
                        target_sell_price=150,
                    )
                )
                self.assertIsNone(
                    _sell_replacement_chain_intent_issue(
                        [order],
                        requested_qty=2,
                        target_sell_price=150,
                    )
                )
                self.assertEqual(
                    _matching_managed_open_sell_orders(
                        [order],
                        "TQQQ",
                        1,
                        expected_alpaca_asset_id="asset-tqqq",
                    ),
                    [order],
                )

        for position_intent in ("sell_to_open", "buy_to_close", "", " SELL_TO_CLOSE ", 1):
            with self.subTest(position_intent=position_intent):
                incompatible_order = {**sell_order, "position_intent": position_intent}
                self.assertTrue(
                    _sell_order_identity_is_consistent(
                        incompatible_order,
                        expected_sell_client_order_id="rsi-exit-TQQQ-1",
                        expected_symbol="TQQQ",
                        expected_alpaca_asset_id="asset-tqqq",
                    )
                )
                self.assertFalse(
                    _sell_order_matches_submission_intent(
                        incompatible_order,
                        requested_qty=2,
                        target_sell_price=150,
                    )
                )
                self.assertIn(
                    "incompatible position intent",
                    _sell_replacement_chain_intent_issue(
                        [incompatible_order],
                        requested_qty=2,
                        target_sell_price=150,
                    ),
                )
                self.assertEqual(
                    _matching_managed_open_sell_orders(
                        [incompatible_order],
                        "TQQQ",
                        1,
                        expected_alpaca_asset_id="asset-tqqq",
                    ),
                    [incompatible_order],
                )

    def test_managed_buy_identity_requires_open_only_position_intent_when_present(self) -> None:
        buy_order = _complete_order_fixture(
            {
                "id": "buy-1",
                "client_order_id": "rsi-buy-TQQQ-20260102",
                "asset_id": "asset-tqqq",
                "symbol": "TQQQ",
                "side": "buy",
                "status": "accepted",
                "qty": "2",
                "limit_price": "105",
            }
        )
        identity_kwargs = {
            "expected_client_order_id": "rsi-buy-TQQQ-20260102",
            "expected_symbol": "TQQQ",
            "expected_alpaca_asset_id": "asset-tqqq",
            "expected_qty": 2,
            "expected_limit_price": 105,
            "require_expected_intent": True,
        }

        for compatible in (
            buy_order,
            {**buy_order, "position_intent": None},
            {**buy_order, "position_intent": "buy_to_open"},
        ):
            with self.subTest(position_intent=compatible.get("position_intent", "<omitted>")):
                self.assertIsNone(_buy_order_identity_issue(compatible, **identity_kwargs))

        for position_intent in ("buy_to_close", "sell_to_open", "", " BUY_TO_OPEN ", 1):
            with self.subTest(position_intent=position_intent):
                issue = _buy_order_identity_issue(
                    {**buy_order, "position_intent": position_intent},
                    **identity_kwargs,
                )
                self.assertIn("incompatible position intent", issue or "")

        root = {**buy_order, "status": "replaced", "replaced_by": "buy-2"}
        successor = {
            **buy_order,
            "id": "buy-2",
            "client_order_id": "broker-replacement",
            "replaces": "buy-1",
            "position_intent": "buy_to_close",
        }
        self.assertIn(
            "incompatible position intent",
            _buy_order_identity_issue(
                successor,
                replacement_chain=[root, successor],
                **identity_kwargs,
            )
            or "",
        )

