    def test_production_alpaca_request_has_absolute_byte_drip_deadline(self) -> None:
        class DripHandler(BaseHTTPRequestHandler):
            def do_GET(self) -> None:
                self.send_response(200)
                self.send_header("Content-Length", "128")
                self.end_headers()
                try:
                    for _ in range(128):
                        self.wfile.write(b"x")
                        self.wfile.flush()
                        time.sleep(0.05)
                except (BrokenPipeError, ConnectionResetError):
                    pass

            def log_message(self, _format: str, *args: object) -> None:
                pass

        server = ThreadingHTTPServer(("127.0.0.1", 0), DripHandler)
        server_thread = threading.Thread(target=server.serve_forever, daemon=True)
        server_thread.start()
        started = time.monotonic()
        try:
            with (
                patch.dict(os.environ, {"NO_PROXY": "127.0.0.1,localhost"}),
                self.assertRaisesRegex(requests.Timeout, "overall deadline"),
            ):
                _alpaca_http_request(
                    "GET",
                    f"http://127.0.0.1:{server.server_port}/drip",
                    cfg=self.cfg(buy=True, timeout_seconds=1),
                    _allow_loopback_test_origin=True,
                    timeout=1,
                    allow_redirects=False,
                )
        finally:
            server.shutdown()
            server.server_close()
            server_thread.join(timeout=2.0)

        self.assertLess(time.monotonic() - started, 2.5)
        self.assertFalse(server_thread.is_alive())

