    def test_alpaca_worker_suppresses_netrc_auth_and_redirect_forwarding(self) -> None:
        received_requests: list[tuple[str, str | None, str | None, str | None]] = []

        class RedirectHandler(BaseHTTPRequestHandler):
            def do_GET(self) -> None:
                received_requests.append(
                    (
                        self.path,
                        self.headers.get("APCA-API-KEY-ID"),
                        self.headers.get("APCA-API-SECRET-KEY"),
                        self.headers.get("Authorization"),
                    )
                )
                self.send_response(302)
                self.send_header("Location", "/redirected")
                self.send_header("Content-Length", "0")
                self.end_headers()

            def log_message(self, _format: str, *args: object) -> None:
                pass

        server = ThreadingHTTPServer(("127.0.0.1", 0), RedirectHandler)
        server_thread = threading.Thread(target=server.serve_forever, daemon=True)
        server_thread.start()
        try:
            with tempfile.TemporaryDirectory() as temporary_directory:
                netrc_path = Path(temporary_directory) / "netrc"
                netrc_path.write_text(
                    "machine 127.0.0.1 login ambient-user password ambient-password\n",
                    encoding="utf-8",
                )
                netrc_path.chmod(0o600)
                with patch.dict(
                    os.environ,
                    {
                        "NETRC": str(netrc_path),
                        "NO_PROXY": "127.0.0.1,localhost",
                    },
                ):
                    broker_response = _alpaca_http_request(
                        "GET",
                        f"http://127.0.0.1:{server.server_port}/initial",
                        cfg=self.cfg(buy=True, timeout_seconds=3),
                        _allow_loopback_test_origin=True,
                        headers={
                            "APCA-API-KEY-ID": "explicit-key",
                            "APCA-API-SECRET-KEY": "explicit-secret",
                        },
                        timeout=3,
                        allow_redirects=False,
                    )
        finally:
            server.shutdown()
            server.server_close()
            server_thread.join(timeout=2.0)

        self.assertEqual(broker_response.status_code, 302)
        self.assertEqual(
            received_requests,
            [("/initial", "explicit-key", "explicit-secret", None)],
        )
        self.assertFalse(server_thread.is_alive())

    def test_http_deadline_worker_reaps_on_base_exception_after_spawn(self) -> None:
        processes: list[subprocess.Popen[bytes]] = []
        real_popen = subprocess.Popen

        def capture_process(*args: object, **kwargs: object) -> subprocess.Popen[bytes]:
            process = real_popen(*args, **kwargs)
            processes.append(process)
            return process

        with (
            patch.object(http_deadline_worker.subprocess, "Popen", side_effect=capture_process),
            patch.object(http_deadline_worker.threading, "Event", side_effect=KeyboardInterrupt),
            self.assertRaises(KeyboardInterrupt),
        ):
            http_deadline_worker.run_deadline_subprocess(
                (sys.executable, "-I", "-c", "import time; time.sleep(5)"),
                {"probe": True},
                deadline=time.monotonic() + 5,
                result_max_bytes=1_024,
                timeout_message="worker timed out",
                connection_error_message="worker failed",
            )

        self.assertEqual(len(processes), 1)
        self.assertIsNotNone(processes[0].returncode)

