    @patch("leveraged_trader.alpaca.requests.get")
    def test_authoritative_alpaca_snapshots_reject_partial_response_semantics(self, mock_get: Mock) -> None:
        client = AlpacaClient(self.cfg(buy=True, sell=True))
        requests_by_endpoint = (
            ("positions", client.positions),
            ("open orders", client.open_orders),
        )
        incomplete_or_unexpected_responses = (
            (201, {}),
            (202, {}),
            (203, {}),
            (204, {}),
            (205, {}),
            (206, {}),
            (207, {}),
            (200, {"Content-Range": "bytes 0-1/100"}),
        )

        for endpoint, request in requests_by_endpoint:
            for status_code, headers in incomplete_or_unexpected_responses:
                partial = raw_response(status_code, "[]")
                partial.headers.update(headers)
                mock_get.return_value = partial
                with (
                    self.subTest(endpoint=endpoint, status_code=status_code, headers=headers),
                    self.assertRaises(HTTPError) as raised,
                ):
                    request()

                self.assertIs(raised.exception.response, partial)
                if status_code == 206:
                    self.assertIn("partial HTTP status 206", str(raised.exception))
                elif headers:
                    self.assertIn("unexpected Content-Range", str(raised.exception))
                else:
                    self.assertIn(f"unexpected HTTP status {status_code}", str(raised.exception))

