    def test_http_error_classification_uses_unredacted_bounded_semantics(self) -> None:
        authentication_response = raw_response(
            403,
            '{"message":"order rejected because the API key is invalid"}',
        )
        with self.assertRaises(HTTPError) as authentication_raised:
            authentication_response.raise_for_status()

        self.assertTrue(
            _authentication_http_error(
                authentication_raised.exception,
                sensitive_values=("key",),
            )
        )
        authentication_diagnostic = _http_error_message(
            authentication_raised.exception,
            sensitive_values=("key",),
        )
        self.assertIn("[redacted credential]", authentication_diagnostic)
        self.assertNotIn("API key", authentication_diagnostic)

        for detail in (
            "order rejected because api_key is invalid",
            "order rejected: authorization failed",
            "order rejected: not authorized",
            "order rejected: access denied",
        ):
            with self.subTest(detail=detail):
                canonical_response = raw_response(403, json.dumps({"message": detail}))
                with self.assertRaises(HTTPError) as canonical_raised:
                    canonical_response.raise_for_status()
                self.assertTrue(_authentication_http_error(canonical_raised.exception))

        oversized_response = raw_response(
            422,
            json.dumps({"message": "order rejected " + "x" * 5_000}),
        )
        with self.assertRaises(HTTPError) as oversized_raised:
            oversized_response.raise_for_status()

        self.assertTrue(_ambiguous_submission_http_error(oversized_raised.exception))

        oversized_forbidden_response = raw_response(
            403,
            json.dumps({"message": "order rejected " + "x" * 5_000}),
        )
        with self.assertRaises(HTTPError) as oversized_forbidden_raised:
            oversized_forbidden_response.raise_for_status()

        self.assertTrue(_authentication_http_error(oversized_forbidden_raised.exception))

    def test_http_error_diagnostics_never_reflect_or_amplify_untrusted_bodies(self) -> None:
        secret = "TOP-SECRET-API-TOKEN"
        padding = "A" * 1_000_000
        bodies = (
            (
                '{"message":"first","message":"second","credential":"' + secret + '","padding":"' + padding + '"}',
                "duplicate JSON object key",
            ),
            (json.dumps(f"noncanonical {secret} {padding}"), "unexpected JSON shape"),
        )
        for body, expected_category in bodies:
            with self.subTest(expected_category=expected_category):
                error_response = raw_response(422, body)
                with self.assertRaises(HTTPError) as raised:
                    error_response.raise_for_status()

                diagnostic = _http_error_message(raised.exception)

                self.assertIn(expected_category, diagnostic)
                self.assertNotIn(secret, diagnostic)
                self.assertNotIn(padding[:1_000], diagnostic)
                self.assertLessEqual(len(diagnostic), 512)
                self.assertTrue(all(char.isprintable() for char in diagnostic))

        canonical_response = raw_response(
            403,
            json.dumps({"message": f"credential: {secret}\u0000\n{padding}"}),
        )
        with self.assertRaises(HTTPError) as raised:
            canonical_response.raise_for_status()
        canonical_diagnostic = _http_error_message(raised.exception)
        self.assertNotIn(secret, canonical_diagnostic)
        self.assertLessEqual(len(canonical_diagnostic), 512)
        self.assertTrue(all(char.isprintable() for char in canonical_diagnostic))

    def test_http_error_diagnostic_redacts_credentials_straddling_its_scan_boundary(self) -> None:
        for secret_length in range(1, 65):
            with self.subTest(secret_length=secret_length):
                secret = "§" * secret_length
                error_response = raw_response(
                    403,
                    json.dumps({"message": "\0" * 1_023 + secret + "LOOKAHEAD-ONLY"}),
                )
                with self.assertRaises(HTTPError) as raised:
                    error_response.raise_for_status()

                diagnostic = _http_error_message(
                    raised.exception,
                    sensitive_values=(secret,),
                )

                self.assertNotIn("§", diagnostic)
                self.assertNotIn("LOOKAHEAD-ONLY", diagnostic)
                self.assertIn("[redacted credential]", diagnostic)
                self.assertLessEqual(len(diagnostic), 512)

    def test_http_error_diagnostic_redacts_credential_reconstituted_at_join(self) -> None:
        secret = "ABC: DEF"
        error_response = raw_response(422, '{"message":"DEF was rejected"}')
        error_response.reason = "provider rejection"
        error_response.url = "https://paper-api.alpaca.markets/v2/orders/ABC"
        with self.assertRaises(HTTPError) as raised:
            error_response.raise_for_status()

        diagnostic = _alpaca_exception_diagnostic(
            raised.exception,
            cfg=AlpacaOrderConfig(
                api_key_id="paper-key",
                api_secret_key=secret,
            ),
        )

        self.assertNotIn(secret, diagnostic)
        self.assertIn("[redacted credential]", diagnostic)
        self.assertLessEqual(len(diagnostic), 512)

