    @patch("leveraged_trader.alpaca.requests.get")
    def test_calendar_requires_canonical_ordered_complete_session_dates(self, mock_get: Mock) -> None:
        client = AlpacaClient(self.cfg(buy=True))
        start = datetime(2025, 12, 22).date()
        end = datetime(2026, 1, 5).date()
        invalid_payloads = (
            ([{}], "canonical date"),
            ([{"date": None}], "canonical date"),
            ([{"date": "not-a-date"}], "canonical date"),
            ([{"date": " 2026-01-05 "}], "canonical date"),
            (
                [{"date": "2026-01-02"}, {"date": "2026-01-02"}, {"date": "2026-01-05"}],
                "duplicate",
            ),
            ([{"date": "2026-01-05"}, {"date": "2026-01-02"}], "out-of-order"),
            ([{"date": "2026-01-02"}], "required next-open session"),
            (
                [{"date": "2025-12-21"}, {"date": "2026-01-05"}],
                "outside the requested date range",
            ),
        )

        for payload, message in invalid_payloads:
            with self.subTest(payload=payload):
                mock_get.return_value = response(200, payload, complete_orders=False)

                with self.assertRaisesRegex(ValueError, message):
                    client.calendar(start, end)

        valid_payload = [{"date": "2026-01-02"}, {"date": "2026-01-05"}]
        mock_get.return_value = response(200, valid_payload, complete_orders=False)
        self.assertEqual(client.calendar(start, end), valid_payload)

    @patch("leveraged_trader.alpaca.requests.delete")
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_authenticated_requests_never_follow_redirects(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
    ) -> None:
        def get_response(url: str, **_kwargs: object) -> Mock:
            if url.endswith("/v2/clock"):
                return response(
                    200,
                    {
                        "is_open": True,
                        "timestamp": "2026-01-05T15:00:00Z",
                        "next_open": "2026-01-06T14:30:00Z",
                    },
                    complete_orders=False,
                )
            if url.endswith("/v2/calendar"):
                return response(
                    200,
                    [{"date": "2026-01-02"}, {"date": "2026-01-05"}],
                    complete_orders=False,
                )
            if url.endswith("/v2/account"):
                return response(200, {"cash": "1000"}, complete_orders=False)
            if url.endswith("/v2/positions/TQQQ"):
                return response(
                    200,
                    {
                        "asset_id": "asset-tqqq",
                        "symbol": "TQQQ",
                        "asset_class": "us_equity",
                        "qty": "2",
                    },
                    complete_orders=False,
                )
            if url.endswith("/v2/positions") or url.endswith("/v2/orders"):
                return response(200, [], complete_orders=False)
            if url.endswith("/v2/assets/TQQQ"):
                return asset_response("TQQQ")
            return response(200, {})

        mock_get.side_effect = get_response
        mock_post.return_value = response(200, {})
        mock_delete.return_value = response(204, {}, complete_orders=False)
        client = AlpacaClient(self.cfg(buy=True, sell=True))

        client.get_order_by_client_order_id("buy-client")
        client.get_order("order-1")
        client.cancel_order("order-1")
        client.market_clock()
        client.calendar(datetime(2026, 1, 2).date(), datetime(2026, 1, 5).date())
        client.cash_notional(eligible_buy_signal_count=1)
        client.position_qty("TQQQ")
        client.positions()
        client.asset("TQQQ")
        client.open_orders()
        client.submit_limit_buy_order(
            symbol="TQQQ",
            qty=1,
            limit_price=100,
            client_order_id="buy-client",
        )
        client.submit_limit_sell_order(
            symbol="TQQQ",
            qty=1,
            limit_price=150,
            client_order_id="sell-client",
        )

        authenticated_calls = [
            *mock_get.call_args_list,
            *mock_post.call_args_list,
            *mock_delete.call_args_list,
        ]
        self.assertEqual(len(authenticated_calls), 12)
        for request_call in authenticated_calls:
            self.assertIs(request_call.kwargs["allow_redirects"], False)
            self.assertEqual(request_call.kwargs["headers"]["APCA-API-KEY-ID"], "key")
            self.assertEqual(request_call.kwargs["headers"]["APCA-API-SECRET-KEY"], "secret")

