    @patch("leveraged_trader.alpaca.requests.get")
    def test_us_equity_position_responses_require_consistent_long_or_short_side(self, mock_get: Mock) -> None:
        client = AlpacaClient(self.cfg(buy=True, sell=True))
        invalid_positions = (
            ({}, "missing or invalid position side"),
            ({"side": "sell"}, "missing or invalid position side"),
            ({"side": "short", "qty": "2"}, "side inconsistent with its signed quantity"),
            ({"side": "long", "qty": "-2"}, "side inconsistent with its signed quantity"),
            ({"side": "long", "qty": "0"}, "side inconsistent with its signed quantity"),
        )
        for endpoint, accessor in (
            ("single", lambda: client.position_qty("asset-tqqq")),
            ("list", client.positions),
        ):
            for overrides, message in invalid_positions:
                with self.subTest(endpoint=endpoint, overrides=overrides):
                    position = {
                        "asset_id": "asset-tqqq",
                        "symbol": "TQQQ",
                        "asset_class": "us_equity",
                        "qty": "2",
                        **overrides,
                    }
                    payload: object = position if endpoint == "single" else [position]
                    mock_get.return_value = response(
                        200,
                        payload,
                        complete_orders=False,
                        complete_asset_classes=False,
                    )
                    with self.assertRaisesRegex(ValueError, message):
                        accessor()

        for side, qty, expected in (("long", "2", 2.0), ("short", "-2", -2.0)):
            with self.subTest(valid_side=side, endpoint="single"):
                position = {
                    "asset_id": "asset-tqqq",
                    "symbol": "TQQQ",
                    "asset_class": "us_equity",
                    "qty": qty,
                    "side": side,
                }
                mock_get.return_value = response(
                    200,
                    position,
                    complete_orders=False,
                    complete_asset_classes=False,
                )
                self.assertEqual(client.position_qty("asset-tqqq"), expected)
            with self.subTest(valid_side=side, endpoint="list"):
                mock_get.return_value = response(
                    200,
                    [position],
                    complete_orders=False,
                    complete_asset_classes=False,
                )
                self.assertEqual(client.positions(), [position])

