    @patch("leveraged_trader.alpaca.requests.post")
    def test_buy_submission_deadline_is_rechecked_after_runtime_file_validation(
        self,
        mock_post: Mock,
    ) -> None:
        client = AlpacaClient(self.cfg(buy=True))
        authorized_next_open = datetime(2026, 1, 5, 14, 30, tzinfo=UTC)
        runtime_file_revalidated = False

        def revalidate_runtime_file() -> None:
            nonlocal runtime_file_revalidated
            runtime_file_revalidated = True

        def current_time() -> datetime:
            self.assertTrue(runtime_file_revalidated)
            # The default 30-second request timeout plus five-second grace
            # makes 14:29:25 the cutoff for a 14:30 open.
            return datetime(2026, 1, 5, 14, 29, 30, tzinfo=UTC)

        with (
            patch(
                "leveraged_trader.alpaca.revalidate_active_sqlite_runtime_file",
                side_effect=revalidate_runtime_file,
            ),
            patch("leveraged_trader.alpaca._market_clock_now", side_effect=current_time),
            self.assertRaisesRegex(RuntimeError, "insufficient dispatch time remains before open"),
        ):
            client.submit_limit_buy_order(
                symbol="TQQQ",
                qty=1,
                limit_price=100,
                client_order_id="buy-client",
                authorized_next_open=authorized_next_open,
            )

        mock_post.assert_not_called()

    @patch("leveraged_trader.alpaca.requests.post")
    def test_buy_submission_uses_broker_ahead_clock_for_dispatch_deadline(
        self,
        mock_post: Mock,
    ) -> None:
        host_now = datetime(2026, 1, 5, 14, 28, 20, tzinfo=UTC)
        broker_now = datetime(2026, 1, 5, 14, 29, 50, tzinfo=UTC)
        next_open = datetime(2026, 1, 5, 14, 30, tzinfo=UTC)

        with (
            patch("leveraged_trader.alpaca._market_clock_now", return_value=host_now),
            patch("leveraged_trader.alpaca._monotonic_now", return_value=100.0),
        ):
            authorization = _buy_submission_dispatch_authorization(
                next_open=next_open,
                broker_clock_timestamp=broker_now,
                request_timeout_seconds=30,
            )
            self.assertTrue(_buy_submission_authorization_window_elapsed(authorization))

            client = AlpacaClient(self.cfg(buy=True))
            with self.assertRaisesRegex(RuntimeError, "insufficient dispatch time remains before open"):
                client.submit_limit_buy_order(
                    symbol="TQQQ",
                    qty=1,
                    limit_price=100,
                    client_order_id="buy-client",
                    authorized_next_open=next_open,
                    dispatch_authorization=authorization,
                )

        # Ten broker seconds remain, so the monotonic write cutoff is five
        # seconds after observation and the timeout-reserving start cutoff is
        # already twenty-five seconds in the past.
        self.assertEqual(authorization.request_write_deadline_monotonic, 105.0)
        self.assertEqual(authorization.dispatch_deadline_monotonic, 75.0)
        mock_post.assert_not_called()

    def test_buy_submission_counts_final_clock_request_latency_against_deadline(self) -> None:
        host_now = datetime(2026, 1, 5, 14, 28, 20, tzinfo=UTC)
        broker_timestamp = datetime(2026, 1, 5, 14, 29, 20, tzinfo=UTC)
        next_open = datetime(2026, 1, 5, 14, 30, tzinfo=UTC)

        with (
            patch("leveraged_trader.alpaca._market_clock_now", return_value=host_now),
            patch("leveraged_trader.alpaca._monotonic_now", return_value=30.0),
        ):
            authorization = _buy_submission_dispatch_authorization(
                next_open=next_open,
                broker_clock_timestamp=broker_timestamp,
                request_timeout_seconds=30,
                broker_clock_request_started_monotonic=0.0,
            )
            self.assertTrue(_buy_submission_authorization_window_elapsed(authorization))

        # The clock response consumed thirty seconds, so the broker timestamp's
        # conservative estimate is 14:29:50 at receipt. Only five seconds remain
        # until the write cutoff, and the thirty-second dispatch budget is gone.
        self.assertEqual(
            authorization.broker_clock_timestamp,
            datetime(2026, 1, 5, 14, 29, 50, tzinfo=UTC),
        )
        self.assertEqual(authorization.request_write_deadline_monotonic, 35.0)
        self.assertEqual(authorization.dispatch_deadline_monotonic, 5.0)

    def test_alpaca_connection_spends_one_absolute_deadline_across_addresses(self) -> None:
        monotonic_time = [0.0]
        sockets = [Mock(name=f"candidate-{index}") for index in range(3)]

        def first_connect(_address: object) -> None:
            monotonic_time[0] += 30.0
            raise TimeoutError("first address timed out")

        def second_connect(_address: object) -> None:
            monotonic_time[0] += 5.0
            raise TimeoutError("second address timed out")

        sockets[0].connect.side_effect = first_connect
        sockets[1].connect.side_effect = second_connect
        address_rows = [
            (socket.AF_INET, socket.SOCK_STREAM, socket.IPPROTO_TCP, "", (f"192.0.2.{index}", 443))
            for index in range(1, 4)
        ]

        with (
            patch("leveraged_trader.alpaca._monotonic_now", side_effect=lambda: monotonic_time[0]),
            patch("leveraged_trader.alpaca.socket.getaddrinfo", return_value=address_rows),
            patch("leveraged_trader.alpaca.socket.socket", side_effect=sockets) as socket_factory,
            _alpaca_request_write_deadline(35.0),
            self.assertRaisesRegex(RuntimeError, "submission window elapsed"),
        ):
            _connect_alpaca_socket_before_write_deadline(
                ("paper-api.alpaca.markets", 443),
                30,
                source_address=None,
                socket_options=None,
            )

        self.assertEqual(socket_factory.call_count, 2)
        sockets[0].settimeout.assert_called_once_with(30.0)
        sockets[1].settimeout.assert_called_once_with(5.0)
        sockets[0].close.assert_called_once_with()
        sockets[1].close.assert_called_once_with()
        sockets[2].connect.assert_not_called()

