    @patch("leveraged_trader.alpaca.AlpacaClient")
    def test_closed_ticker_migration_failure_does_not_block_active_protection(
        self,
        mock_client_factory: Mock,
    ) -> None:
        broker_events: list[str] = []
        client = mock_client_factory.return_value
        client.positions.return_value = [
            {
                "asset_id": "asset-active",
                "symbol": "ACTIVE2",
                "asset_class": "us_equity",
                "qty": "2",
                "side": "long",
            }
        ]
        unavailable = HTTPError("503 closed-order lookup unavailable")
        unavailable.response = response(
            503,
            {"message": "closed-order lookup unavailable"},
            complete_orders=False,
        )

        def fail_closed_lookup(_order_id: str) -> None:
            broker_events.append("closed_lookup")
            raise unavailable

        client.get_order.side_effect = fail_closed_lookup

        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            save_alpaca_managed_buy_order(
                conn,
                symbol="ACTIVE1",
                alpaca_asset_id="asset-active",
                signal_symbol="ACTIVE-SIGNAL",
                buy_rsi=30,
                profit_target_multiple=1.5,
                buy_signal_date="2020-01-02",
                buy_client_order_id="rsi-buy-ACTIVE1-20200102",
                buy_alpaca_order_id=None,
                buy_submitted_at="2020-01-02T14:30:00Z",
                buy_status="filled",
            )
            mark_alpaca_managed_buy_filled(
                conn,
                1,
                buy_status="filled",
                filled_qty=2,
                filled_avg_price=100,
                filled_at="2020-01-02T14:31:00Z",
                target_sell_price=150,
            )
            closed_id = save_alpaca_managed_buy_order(
                conn,
                symbol="CLOSED1",
                alpaca_asset_id="asset-closed",
                signal_symbol="CLOSED-SIGNAL",
                buy_rsi=30,
                profit_target_multiple=1.5,
                buy_signal_date="2026-07-01",
                buy_client_order_id="rsi-buy-CLOSED1-20260701",
                buy_alpaca_order_id="closed-buy",
                buy_submitted_at="2026-07-01T14:30:00Z",
                buy_status="identity_mismatch",
            )
            conn.execute(
                "UPDATE alpaca_managed_positions SET closed_at = CURRENT_TIMESTAMP WHERE id = ?",
                (closed_id,),
            )
            conn.commit()

            def record_active_protection(**_kwargs: object) -> None:
                broker_events.append("active_protective_submit")
                rows = _kwargs["rows"]
                assert isinstance(rows, list)
                rows.append(
                    {
                        "Position ID": 1,
                        "Asset": "ACTIVE2",
                        "Action": "sell",
                        "Status": "submitted",
                        "Buy Client Order ID": "rsi-buy-ACTIVE1-20200102",
                        "Sell Client Order ID": _kwargs["sell_client_order_id"],
                        "Qty": 2,
                        "Limit Price": 150,
                        "Alpaca Order ID": "active-sell",
                        "Message": "active position received protective coverage",
                        "_Systemic Failure": False,
                        "_Required Failure": False,
                    }
                )

            with patch(
                "leveraged_trader.alpaca._submit_managed_gtc_sell",
                side_effect=record_active_protection,
            ) as mock_submit:
                migrations = migrate_alpaca_managed_position_symbols(
                    conn,
                    self.cfg(buy=True, sell=True),
                    include_closed=False,
                )
                conn.commit()
                with self.assertRaises(AlpacaReconciliationError) as raised:
                    reconcile_alpaca_managed_positions(
                        conn,
                        self.cfg(buy=True, sell=True),
                        migrate_closed_symbols=True,
                    )
            managed = load_alpaca_managed_positions(conn).set_index("id")

        self.assertEqual(migrations, {"ACTIVE1": "ACTIVE2"})
        self.assertEqual(managed.loc[1, "symbol"], "ACTIVE2")
        self.assertEqual(managed.loc[closed_id, "symbol"], "CLOSED1")
        self.assertEqual(raised.exception.results["Status"].tolist(), ["submitted", "error"])
        closed_result = raised.exception.results.loc[raised.exception.results["Position ID"].eq(closed_id)].iloc[0]
        self.assertEqual(closed_result["Action"], "closed_audit")
        self.assertEqual(broker_events[0], "active_protective_submit")
        self.assertIn("closed_lookup", broker_events[1:])
        mock_submit.assert_called_once()
        self.assertEqual(mock_submit.call_args.kwargs["symbol"], "ACTIVE2")

