    @patch("leveraged_trader.alpaca.requests.delete")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_production_reconciliation_migrates_then_cancels_active_wrong_intent_buy(
        self,
        mock_get: Mock,
        mock_delete: Mock,
    ) -> None:
        from leveraged_trader.workflow import _reconcile_alpaca_managed_positions_for_db

        asset_id = "asset-echo"
        wrong_intent_buy = {
            "id": "buy-1",
            "client_order_id": "rsi-buy-SATG-20260618",
            "asset_id": asset_id,
            "symbol": "SATG",
            "side": "buy",
            "position_intent": "buy_to_close",
            "status": "accepted",
            "qty": "2",
            "filled_qty": "0",
            "limit_price": "12.20",
        }
        mock_get.side_effect = [
            response(
                200,
                [{"asset_id": asset_id, "symbol": "ECHX", "qty": "2"}],
            ),
            response(200, wrong_intent_buy),
            response(200, wrong_intent_buy),
        ]
        cancellation_statuses: list[tuple[str, str]] = []
        mock_delete.return_value = response(204, {}, complete_orders=False)

        with tempfile.TemporaryDirectory() as tmp:
            db_path = str(Path(tmp) / "state.sqlite")
            with closing(sqlite3.connect(db_path)) as conn, conn:
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="SATG",
                    signal_symbol="SATS",
                    buy_rsi=30,
                    profit_target_multiple=1.1,
                    buy_signal_date="2026-06-18",
                    buy_client_order_id="rsi-buy-SATG-20260618",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-06-22T13:30:00Z",
                    buy_status="accepted",
                    buy_order_qty=2,
                    buy_order_limit_price=12.20,
                )

            def cancel_after_durable_quarantine(*args: object, **_kwargs: object) -> Mock:
                with closing(sqlite3.connect(db_path)) as observer:
                    cancellation_statuses.append(
                        observer.execute(
                            "SELECT symbol, buy_status FROM alpaca_managed_positions WHERE id = 1"
                        ).fetchone()
                    )
                return response(204, {}, complete_orders=False)

            mock_delete.side_effect = cancel_after_durable_quarantine
            with self.assertRaises(AlpacaReconciliationError) as raised:
                _reconcile_alpaca_managed_positions_for_db(
                    db_path,
                    self.cfg(buy=True, sell=True),
                )
            with closing(sqlite3.connect(db_path)) as conn:
                managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertEqual(
            raised.exception.results["Status"].tolist(),
            ["symbol_migrated", "pending_cancel"],
        )
        self.assertIn(
            "incompatible position intent",
            raised.exception.results.iloc[-1]["Message"],
        )
        self.assertEqual(cancellation_statuses, [("ECHX", "pending_cancel")])
        self.assertEqual(managed["symbol"], "ECHX")
        self.assertEqual(managed["buy_status"], "pending_cancel")
        self.assertTrue(pd.isna(managed["filled_qty"]))
        self.assertTrue(mock_delete.call_args.args[0].endswith("/v2/orders/buy-1"))

