    @patch("leveraged_trader.alpaca.AlpacaClient")
    def test_ticker_migrations_remain_pending_until_final_commit(
        self,
        mock_client_factory: Mock,
    ) -> None:
        class FinalCommitFailureConnection(sqlite3.Connection):
            fail_next_commit = False

            def commit(self) -> None:
                if self.fail_next_commit:
                    self.fail_next_commit = False
                    raise sqlite3.OperationalError("forced final migration commit failure")
                super().commit()

        mock_client_factory.return_value.positions.return_value = [
            {
                "asset_id": "asset-1",
                "symbol": "NEW",
                "asset_class": "us_equity",
                "qty": "1",
                "side": "long",
            },
        ]

        for closed in (False, True):
            with self.subTest(closed=closed), tempfile.TemporaryDirectory() as tmp_dir:
                db_path = str(Path(tmp_dir) / "symbol-migration.sqlite")
                with closing(sqlite3.connect(db_path)) as setup:
                    init_state_db(setup)
                    save_alpaca_managed_buy_order(
                        setup,
                        symbol="OLD",
                        alpaca_asset_id="asset-1",
                        signal_symbol="QQQ",
                        buy_rsi=30,
                        profit_target_multiple=1.1,
                        buy_signal_date="2026-06-18",
                        buy_client_order_id="rsi-buy-OLD-20260618",
                        buy_alpaca_order_id=None,
                        buy_submitted_at=None,
                        buy_status="identity_mismatch" if closed else "accepted",
                    )
                    if closed:
                        setup.execute("UPDATE alpaca_managed_positions SET closed_at = CURRENT_TIMESTAMP")
                        setup.commit()

                conn = sqlite3.connect(db_path, factory=FinalCommitFailureConnection)
                try:
                    migrations = migrate_alpaca_managed_position_symbols(
                        conn,
                        self.cfg(buy=True, sell=True),
                        include_active=not closed,
                        include_closed=closed,
                    )
                    self.assertEqual(migrations, {"OLD": "NEW"})
                    self.assertTrue(conn.in_transaction)
                    conn.fail_next_commit = True
                    with self.assertRaisesRegex(
                        sqlite3.OperationalError,
                        "forced final migration commit failure",
                    ):
                        conn.commit()
                    conn.rollback()
                finally:
                    conn.close()

                with sqlite3.connect(db_path) as observer:
                    self.assertEqual(
                        observer.execute("SELECT symbol, alpaca_asset_id FROM alpaca_managed_positions").fetchall(),
                        [("OLD", "asset-1")],
                    )

