    def test_exit_client_order_namespace_is_durable_and_buy_specific(self) -> None:
        first_namespace = alpaca_exit_order_namespace("rsi-buy-TQQQ-20260102")
        repeated_namespace = alpaca_exit_order_namespace("rsi-buy-TQQQ-20260102")
        second_namespace = alpaca_exit_order_namespace("rsi-buy-TQQQ-20260105")

        first_id = _alpaca_exit_client_order_id(
            "TQQQ",
            1,
            order_namespace=first_namespace,
        )
        recreated_db_id = _alpaca_exit_client_order_id(
            "TQQQ",
            1,
            order_namespace=second_namespace,
        )

        self.assertEqual(first_namespace, repeated_namespace)
        self.assertNotEqual(first_namespace, second_namespace)
        self.assertNotEqual(first_id, recreated_db_id)
        self.assertIn(first_namespace, first_id)

