    def test_immediate_sell_wrong_position_intent_is_fenced_before_cancellation(self) -> None:
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_filled_managed_buy(conn)
            sell_client_order_id = "rsi-exit-TQQQ-1"
            client = Mock()
            client.cfg = self.cfg(sell=True)
            client.get_order_by_client_order_id.return_value = response(404, {})
            client.open_orders.return_value = []
            client.positions.return_value = [
                {
                    "asset_id": "asset-tqqq",
                    "symbol": "TQQQ",
                    "asset_class": "us_equity",
                    "qty": "2",
                    "side": "long",
                }
            ]
            client.submit_limit_sell_order.return_value = response(
                200,
                {
                    "id": "sell-wrong-intent",
                    "client_order_id": sell_client_order_id,
                    "asset_id": "asset-tqqq",
                    "symbol": "TQQQ",
                    "side": "sell",
                    "position_intent": "sell_to_open",
                    "status": "partially_filled",
                    "qty": "2",
                    "filled_qty": "1",
                    "filled_avg_price": "160",
                    "limit_price": "150",
                },
            )
            durable_state_at_cancel: list[tuple[object, ...]] = []

            def cancel_after_durable_quarantine(order_id: str) -> Mock:
                self.assertEqual(order_id, "sell-wrong-intent")
                durable_state_at_cancel.append(
                    conn.execute(
                        "SELECT sell_status, sell_alpaca_order_id, sold_qty FROM alpaca_managed_positions WHERE id = 1"
                    ).fetchone()
                )
                return response(204, {}, complete_orders=False)

            client.cancel_order.side_effect = cancel_after_durable_quarantine
            rows: list[dict] = []
            _submit_managed_gtc_sell(
                conn=conn,
                client=client,
                rows=rows,
                position_id=1,
                symbol="TQQQ",
                buy_client_order_id="rsi-buy-TQQQ-20260102",
                sell_client_order_id=sell_client_order_id,
                filled_qty=2,
                target_sell_price=150,
                increment_renewal_count=False,
                replacement_message="test managed sell",
                live_position_qty=2,
                expected_alpaca_asset_id="asset-tqqq",
            )
            managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertEqual(rows[0]["Status"], "pending_cancel")
        self.assertIn("incompatible position intent", rows[0]["Message"])
        self.assertEqual(managed["sell_status"], "pending_cancel")
        self.assertEqual(managed["sell_alpaca_order_id"], "sell-wrong-intent")
        self.assertEqual(managed["sold_qty"], 0)
        self.assertEqual(managed["sold_value"], 0)
        self.assertTrue(pd.isna(managed["realized_pl"]))
        self.assertEqual(managed["remaining_qty"], 2)
        self.assertEqual(durable_state_at_cancel, [("pending_cancel", "sell-wrong-intent", 0)])
        client.cancel_order.assert_called_once_with("sell-wrong-intent")

    def test_final_sell_fence_rejects_invalid_or_non_long_position_before_post(self) -> None:
        invalid_positions = (
            ({"side": "long", "qty": "2"}, "non-US-equity asset class"),
            (
                {"asset_class": "global_equity", "side": "long", "qty": "2"},
                "non-US-equity asset class",
            ),
            ({"asset_class": "us_equity", "qty": "2"}, "missing or invalid position side"),
            (
                {"asset_class": "us_equity", "side": "short", "qty": "2"},
                "side inconsistent with its signed quantity",
            ),
            (
                {"asset_class": "us_equity", "side": "short", "qty": "-2"},
                "not a long holding",
            ),
        )
        for position_fields, expected_message in invalid_positions:
            with self.subTest(position=position_fields), closing(sqlite3.connect(":memory:")) as conn:
                init_state_db(conn)
                self.seed_filled_managed_buy(conn)
                buy_client_order_id = "rsi-buy-TQQQ-20260102"
                sell_order_namespace = alpaca_exit_order_namespace(buy_client_order_id)
                client = Mock()
                client.cfg = self.cfg(buy=True, sell=True)
                client.get_order_by_client_order_id.return_value = response(404, {})
                client.open_orders.return_value = []
                client.positions.return_value = [
                    {
                        "asset_id": "asset-tqqq",
                        "symbol": "TQQQ",
                        **position_fields,
                    }
                ]
                rows: list[dict] = []

                _submit_managed_gtc_sell(
                    conn=conn,
                    client=client,
                    rows=rows,
                    position_id=1,
                    symbol="TQQQ",
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=_alpaca_exit_client_order_id(
                        "TQQQ",
                        1,
                        order_namespace=sell_order_namespace,
                    ),
                    filled_qty=2,
                    target_sell_price=150,
                    increment_renewal_count=False,
                    replacement_message="submitted managed GTC limit sell",
                    live_position_qty=2,
                    sell_order_namespace=sell_order_namespace,
                    expected_alpaca_asset_id="asset-tqqq",
                )

            client.submit_limit_sell_order.assert_not_called()
            self.assertEqual(rows[-1]["Status"], "error")
            self.assertIn(expected_message, rows[-1]["Message"])

    def test_initial_sell_atomic_claim_rejects_same_quantity_parent_status_change(self) -> None:
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_filled_managed_buy(conn)
            client = Mock()
            rows: list[dict] = []
            parent_changed: list[bool] = []

            def snapshot_then_reopen_parent(*args: object, **kwargs: object) -> object:
                snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
                    *args,
                    **kwargs,
                )
                parent_changed.append(
                    mark_alpaca_managed_buy_filled(
                        conn,
                        1,
                        buy_status="partially_filled",
                        filled_qty=2,
                        filled_avg_price=100,
                        filled_at=None,
                        target_sell_price=150,
                        buy_alpaca_order_id="buy-1",
                        expected_buy_status="filled",
                        expected_buy_alpaca_order_id="buy-1",
                        expected_filled_qty=2,
                        expected_filled_avg_price=100,
                        expected_target_sell_price=150,
                        expected_sell_client_order_id=None,
                    )
                )
                return snapshot

            with patch(
                "leveraged_trader.alpaca.alpaca_managed_sell_renewal_snapshot_if_current",
                side_effect=snapshot_then_reopen_parent,
            ):
                _submit_managed_gtc_sell(
                    conn=conn,
                    client=client,
                    rows=rows,
                    position_id=1,
                    symbol="TQQQ",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    sell_client_order_id="rsi-exit-TQQQ-1",
                    filled_qty=2,
                    target_sell_price=150,
                    increment_renewal_count=False,
                    replacement_message="submitted managed GTC limit sell",
                    live_position_qty=2,
                    expected_alpaca_asset_id="asset-tqqq",
                )
            managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertEqual(parent_changed, [True])
        self.assertEqual(rows[0]["Status"], "superseded")
        self.assertEqual(managed["buy_status"], "partially_filled")
        self.assertTrue(pd.isna(managed["sell_client_order_id"]))
        self.assertTrue(pd.isna(managed["sell_submission_retry_claimed_at"]))
        self.assertTrue(pd.isna(managed["closed_at"]))
        client.submit_limit_sell_order.assert_not_called()

