    def test_deterministic_buy_client_order_ids_distinguish_dots_and_hyphens_and_reuse_legacy_state(
        self,
    ) -> None:
        dotted_id = _alpaca_client_order_id("buy", "BRK.B", "2026-01-02")
        hyphenated_id = _alpaca_client_order_id("buy", "BRK-B", "2026-01-02")

        self.assertEqual(dotted_id, "rsi-buy-BRK.B-20260102")
        self.assertEqual(hyphenated_id, "rsi-buy-BRK-B-20260102")
        self.assertNotEqual(dotted_id, hyphenated_id)
        self.assertLessEqual(max(len(dotted_id), len(hyphenated_id)), 128)
        self.assertEqual(
            _alpaca_buy_client_order_id_for_signal(None, "BRK.B", "2026-01-02"),
            dotted_id,
        )

        with closing(sqlite3.connect(":memory:")) as conn:
            init_state_db(conn)
            self.assertEqual(
                _alpaca_buy_client_order_id_for_signal(conn, "BRK-B", "2026-01-02"),
                "rsi-buy-BRK-B-20260102",
            )
            save_alpaca_managed_buy_order(
                conn,
                symbol="BRK.B",
                signal_symbol="SPY",
                buy_rsi=30,
                profit_target_multiple=1.5,
                buy_signal_date="2026-01-02",
                buy_client_order_id="rsi-buy-BRK-B-20260102",
                buy_alpaca_order_id=None,
                buy_submitted_at=None,
                buy_status="submission_not_found",
            )

            self.assertEqual(
                _alpaca_buy_client_order_id_for_signal(conn, "BRK.B", "2026-01-02"),
                "rsi-buy-BRK-B-20260102",
            )
            self.assertEqual(
                _alpaca_buy_client_order_id_for_signal(conn, "BRK-B", "2026-01-02"),
                "rsi-buy-v2~42524B2D42-20260102",
            )

