    @patch("leveraged_trader.alpaca._latest_market_price", return_value=100.0)
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_managed_buy_losing_final_local_fence_does_not_post_after_new_owner_claims(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        mock_get.side_effect = [
            response(404, {}),
            response(200, []),
            asset_response("TQQQ", status="active", tradable=True),
            response(404, {}),
            response(
                200,
                {
                    "is_open": False,
                    "timestamp": "2026-01-05T13:30:00Z",
                    "next_open": "2026-01-05T14:30:00Z",
                },
            ),
            response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}]),
            response(200, {"cash": "3000"}),
            *final_managed_buy_pre_submit_responses(),
        ]
        interleaving: dict[str, object] = {}

        with tempfile.TemporaryDirectory() as tmp:
            db_path = Path(tmp) / "state.sqlite"
            with closing(sqlite3.connect(db_path)) as setup_conn, setup_conn:
                init_state_db(setup_conn)
            with (
                closing(sqlite3.connect(db_path)) as owner_conn,
                owner_conn,
                closing(sqlite3.connect(db_path)) as observer_conn,
                observer_conn,
            ):

                def close_expired_generation_then_claim_new_owner(
                    conn: sqlite3.Connection,
                    position_id: int,
                    **kwargs: object,
                ) -> int | None:
                    observer_conn.execute(
                        "UPDATE alpaca_managed_positions "
                        "SET buy_submission_claimed_at = '2020-01-01T00:00:00Z' WHERE id = ?",
                        (position_id,),
                    )
                    observer_conn.commit()
                    stale_revision = int(
                        observer_conn.execute(
                            "SELECT state_revision FROM alpaca_managed_positions WHERE id = ?",
                            (position_id,),
                        ).fetchone()[0]
                    )
                    interleaving["closed"] = close_alpaca_managed_buy_if_current_and_unfilled(
                        observer_conn,
                        position_id,
                        expected_buy_status="submission_pending",
                        expected_buy_alpaca_order_id=None,
                        expected_buy_submission_attempt_count=int(kwargs["expected_buy_submission_attempt_count"]),
                        expected_state_revision=stale_revision,
                        buy_status="submission_not_found",
                        notes="expired missing-order observation won before the final owner fence",
                    )
                    interleaving["new_claim"] = claim_alpaca_managed_buy_intent(
                        observer_conn,
                        symbol="RENAMED",
                        alpaca_asset_id="asset-tqqq",
                        signal_symbol="QQQ",
                        buy_rsi=30,
                        profit_target_multiple=1.5,
                        buy_signal_date="2026-01-03",
                        buy_client_order_id="rsi-buy-RENAMED-20260103",
                        buy_order_qty=1,
                        buy_order_limit_price=105,
                    )
                    return confirm_alpaca_managed_buy_submission(
                        conn,
                        position_id,
                        expected_buy_submission_attempt_count=int(kwargs["expected_buy_submission_attempt_count"]),
                        expected_state_revision=int(kwargs["expected_state_revision"]),
                        expected_buy_order_qty=int(kwargs["expected_buy_order_qty"]),
                        expected_buy_order_limit_price=float(kwargs["expected_buy_order_limit_price"]),
                        claimed_at=str(kwargs["claimed_at"]),
                    )

                with patch(
                    "leveraged_trader.alpaca.confirm_alpaca_managed_buy_submission",
                    side_effect=close_expired_generation_then_claim_new_owner,
                ):
                    result = submit_alpaca_paper_buy_orders(
                        pd.DataFrame(
                            [
                                {
                                    "Asset": "TQQQ",
                                    "RSI Symbol": "QQQ",
                                    "Date": "2026-01-02",
                                    "Buy RSI": 30.0,
                                    "Sell Return Multiple": 1.5,
                                }
                            ]
                        ),
                        self.cfg(buy=True),
                        conn=owner_conn,
                    )
                rows = owner_conn.execute(
                    "SELECT buy_client_order_id, buy_status, buy_alpaca_order_id, closed_at "
                    "FROM alpaca_managed_positions ORDER BY id"
                ).fetchall()

        new_claim = interleaving["new_claim"]
        self.assertEqual(result.loc[0, "Status"], "superseded")
        self.assertTrue(interleaving["closed"])
        self.assertTrue(new_claim.claimed)
        self.assertEqual(rows[0][1:3], ("submission_not_found", None))
        self.assertIsNotNone(rows[0][3])
        self.assertEqual(rows[1][1:3], ("submission_pending", None))
        self.assertIsNone(rows[1][3])
        mock_post.assert_not_called()

