            with self.subTest(next_open=next_open):
                mock_get.reset_mock()
                mock_post.reset_mock()
                mock_get.side_effect = [
                    response(404, {}),
                    response(200, []),
                    asset_response("TQQQ", status="active", tradable=True),
                    response(404, {}),
                    response(
                        200,
                        {
                            "is_open": False,
                            "timestamp": "2026-01-05T13:30:00Z",
                            "next_open": next_open,
                        },
                    ),
                ]

