    @patch("leveraged_trader.alpaca.requests.get")
    def test_managed_buy_defers_when_runtime_revalidation_crosses_the_dispatch_deadline(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        runtime_file_revalidated = False

        def get_response(url: str, **_kwargs: object) -> Mock:
            if "/v2/orders:by_client_order_id" in url or "/v2/positions/" in url:
                return response(404, {})
            if url.endswith("/v2/orders"):
                return response(200, [])
            if "/v2/assets/" in url:
                return asset_response("TQQQ", status="active", tradable=True)
            if url.endswith("/v2/clock"):
                return response(
                    200,
                    {
                        "is_open": False,
                        "timestamp": "2026-01-05T13:30:00Z",
                        "next_open": "2026-01-05T14:30:00Z",
                    },
                )
            if url.endswith("/v2/calendar"):
                return response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}])
            if url.endswith("/v2/account"):
                return response(200, {"cash": "3000"})
            raise AssertionError(f"unexpected Alpaca GET: {url}")

        def revalidate_runtime_file() -> None:
            nonlocal runtime_file_revalidated
            runtime_file_revalidated = True

        def current_time() -> datetime:
            if runtime_file_revalidated:
                # Cross the timeout-plus-grace cutoff, but remain before open.
                return datetime(2026, 1, 5, 14, 29, 30, tzinfo=UTC)
            return datetime(2026, 1, 5, 13, 30, tzinfo=UTC)

        mock_get.side_effect = get_response
        with (
            closing(sqlite3.connect(":memory:")) as conn,
            conn,
            patch(
                "leveraged_trader.alpaca.revalidate_active_sqlite_runtime_file",
                side_effect=revalidate_runtime_file,
            ),
            patch("leveraged_trader.alpaca._market_clock_now", side_effect=current_time),
        ):
            init_state_db(conn)
            result = _submit_alpaca_paper_buy_orders(
                pd.DataFrame(
                    [
                        {
                            "Asset": "TQQQ",
                            "RSI Symbol": "QQQ",
                            "Date": "2026-01-02",
                            "RSI Observation Date": "2026-01-02",
                            "Buy RSI": 30.0,
                            "Sell Return Multiple": 1.5,
                        }
                    ]
                ),
                self.cfg(buy=True),
                conn,
            )
            managed = load_alpaca_managed_positions(conn)

        self.assertTrue(runtime_file_revalidated)
        self.assertEqual(result.loc[0, "Status"], "deferred")
        self.assertIn("before the broker POST", result.loc[0, "Message"])
        self.assertEqual(managed.loc[0, "buy_status"], "submission_failed")
        self.assertFalse(pd.isna(managed.loc[0, "closed_at"]))
        mock_post.assert_not_called()

    @patch("leveraged_trader.alpaca._latest_market_price", return_value=100.0)
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_runtime_identity_failure_is_fatal_but_proven_undispatched_and_retryable(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        calls_by_endpoint: dict[str, int] = {}

        def get_response(url: str, **_kwargs: object) -> Mock:
            endpoint = url.split("/v2/", maxsplit=1)[-1]
            calls_by_endpoint[endpoint] = calls_by_endpoint.get(endpoint, 0) + 1
            if endpoint.startswith("orders:by_client_order_id") or endpoint.startswith("positions/"):
                return response(404, {})
            if endpoint == "orders":
                return response(200, [])
            if endpoint.startswith("assets/"):
                return asset_response("TQQQ", status="active", tradable=True)
            if endpoint == "clock":
                return response(
                    200,
                    {
                        "is_open": False,
                        "timestamp": "2026-01-05T13:30:00Z",
                        "next_open": "2026-01-05T14:30:00Z",
                    },
                )
            if endpoint == "calendar":
                return response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}])
            if endpoint == "account":
                return response(200, {"cash": "3000"})
            raise AssertionError(f"unexpected Alpaca GET: {url}")

        mock_get.side_effect = get_response
        signal = pd.DataFrame(
            [
                {
                    "Asset": "TQQQ",
                    "RSI Symbol": "QQQ",
                    "Date": "2026-01-02",
                    "RSI Observation Date": "2026-01-02",
                    "Buy RSI": 30.0,
                    "Sell Return Multiple": 1.5,
                }
            ]
        )

        with (
            closing(sqlite3.connect(":memory:")) as conn,
            conn,
            patch(
                "leveraged_trader.alpaca.revalidate_active_sqlite_runtime_file",
                side_effect=OSError("database changed identity"),
            ) as mock_revalidate,
            patch(
                "leveraged_trader.alpaca._market_clock_now",
                return_value=datetime(2026, 1, 5, 13, 30, tzinfo=UTC),
            ),
        ):
            init_state_db(conn)
            with self.assertRaises(AlpacaBuyBatchError) as raised:
                _submit_alpaca_paper_buy_orders(signal, self.cfg(buy=True), conn)
            managed = load_alpaca_managed_positions(conn)
            original_attempt_count = int(managed.loc[0, "buy_submission_attempt_count"])

            retry_claim = claim_alpaca_managed_buy_intent(
                conn,
                symbol="TQQQ",
                alpaca_asset_id="asset-tqqq",
                signal_symbol="QQQ",
                buy_rsi=30.0,
                profit_target_multiple=1.5,
                buy_signal_date="2026-01-02",
                buy_client_order_id="rsi-buy-TQQQ-20260102",
                buy_order_qty=float(managed.loc[0, "buy_order_qty"]),
                buy_order_limit_price=float(managed.loc[0, "buy_order_limit_price"]),
                allow_retry_after_not_found=True,
            )
            retried = load_alpaca_managed_positions(conn)

        self.assertEqual(raised.exception.results.loc[0, "Status"], "error")
        self.assertIn("local runtime fence", raised.exception.results.loc[0, "Message"])
        self.assertFalse(raised.exception.broker_side_effects_possible)
        self.assertEqual(managed.loc[0, "buy_status"], "submission_not_found")
        self.assertFalse(pd.isna(managed.loc[0, "closed_at"]))
        self.assertTrue(pd.isna(managed.loc[0, "buy_alpaca_order_id"]))
        self.assertTrue(retry_claim.claimed)
        self.assertEqual(retry_claim.position_id, int(managed.loc[0, "id"]))
        self.assertEqual(int(retried.loc[0, "buy_submission_attempt_count"]), original_attempt_count + 1)
        self.assertEqual(retried.loc[0, "buy_status"], "submission_pending")
        self.assertTrue(pd.isna(retried.loc[0, "closed_at"]))
        self.assertEqual(mock_get.call_count, 11)
        self.assertEqual(calls_by_endpoint["clock"], 2)
        self.assertEqual(calls_by_endpoint["orders"], 2)
        self.assertEqual(mock_revalidate.call_count, 1)
        mock_post.assert_not_called()

