    @patch("leveraged_trader.alpaca.AlpacaClient")
    @patch("leveraged_trader.alpaca._latest_market_price", return_value=100.0)
    def test_configured_credentials_are_redacted_from_public_buy_diagnostics_and_notes(
        self,
        _mock_latest_price: Mock,
        mock_client_factory: Mock,
    ) -> None:
        client = mock_client_factory.return_value
        client.get_order_by_client_order_id.return_value = response(404, {})
        client.open_orders.return_value = []
        client.asset.return_value = {
            "id": "asset-tqqq",
            "class": "us_equity",
            "symbol": "TQQQ",
            "tradable": True,
            "status": "active",
        }
        client.position_qty.return_value = 0.0
        client.positions.return_value = []
        client.market_clock.return_value = {
            "is_open": False,
            "timestamp": "2026-01-05T13:30:00Z",
            "next_open": "2026-01-05T14:30:00Z",
        }
        client.calendar.return_value = [{"date": "2026-01-02"}, {"date": "2026-01-05"}]
        client.cash_notional.return_value = 3000.0

        for api_key_id, secret, leaked_probe in (
            (
                "opaque-key-id-123456789",
                "plainopaquecredential123456789",
                "plainopaquecredential123456789",
            ),
            (
                "opaque-key-id-123456789",
                "LONG-OPAQUE-CREDENTIAL-" + "X" * 1_000_000,
                "LONG-OPAQUE-CREDENTIAL-" + "X" * 40,
            ),
            (
                "PREFIX-1234567890",
                "PREFIX-1234567890" + "X" * 1_000_000,
                "X" * 64,
            ),
        ):
            with self.subTest(secret_length=len(secret)), closing(sqlite3.connect(":memory:")) as conn, conn:
                init_state_db(conn)
                cfg = AlpacaOrderConfig(
                    enabled=True,
                    api_key_id=f" {api_key_id} ",
                    api_secret_key=f" {secret} ",
                )
                client.submit_limit_buy_order.return_value = error_response(
                    403,
                    {"message": secret},
                )

                with self.assertRaises(AlpacaBuyBatchError) as raised:
                    submit_alpaca_paper_buy_orders(
                        pd.DataFrame(
                            [
                                {
                                    "Asset": "TQQQ",
                                    "RSI Symbol": "QQQ",
                                    "Date": "2026-01-02",
                                    "Buy RSI": 30.0,
                                    "Sell Return Multiple": 1.5,
                                }
                            ]
                        ),
                        cfg,
                        conn=conn,
                    )
                managed = load_alpaca_managed_positions(conn)

                public_diagnostic = str(raised.exception) + raised.exception.results.to_string()
                durable_diagnostic = str(managed.loc[0, "notes"])
                self.assertNotIn(leaked_probe, public_diagnostic)
                self.assertNotIn(leaked_probe, durable_diagnostic)
                self.assertIn("[redacted credential]", public_diagnostic)
                self.assertLessEqual(len(raised.exception.results.loc[0, "Message"]), 512)

