    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_deterministic_buy_replacement_lookup_failure_requires_reconciliation(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        deterministic_root = {
            "id": "buy-root",
            "client_order_id": "rsi-buy-TQQQ-20260102",
            "asset_id": "asset-tqqq",
            "symbol": "TQQQ",
            "side": "buy",
            "type": "limit",
            "time_in_force": "day",
            "extended_hours": False,
            "status": "pending_replace",
            "qty": "2",
            "limit_price": "105",
            "filled_qty": "0",
            "replaced_by": "buy-leaf",
        }
        signal = pd.DataFrame([{"Asset": "TQQQ", "Date": "2026-01-02", "RSI Observation Date": "2026-01-02"}])
        cases = {
            "exact lookup": [response(200, deterministic_root), requests.Timeout("successor unavailable")],
            "open snapshot": [
                response(404, {}),
                response(200, [deterministic_root]),
                requests.Timeout("successor unavailable"),
            ],
        }

        for source, side_effect in cases.items():
            with self.subTest(source=source):
                mock_get.reset_mock(side_effect=True)
                mock_post.reset_mock()
                mock_get.side_effect = side_effect

                with self.assertRaises(AlpacaBuyBatchError) as raised:
                    submit_alpaca_paper_buy_orders(signal, self.cfg(buy=True))

                result = raised.exception.results.iloc[0]
                self.assertEqual(result["Status"], "error")
                self.assertEqual(result["Alpaca Order ID"], "buy-root")
                self.assertIn("successor unavailable", result["Message"])
                self.assertIn("status=pending_replace", result["Message"])
                self.assertTrue(raised.exception.broker_side_effects_possible)
                mock_post.assert_not_called()

