    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_deterministic_buy_resolution_failure_aborts_other_eligible_signal(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        deterministic_root = {
            "id": "buy-root",
            "client_order_id": "rsi-buy-TQQQ-20260102",
            "asset_id": "asset-tqqq",
            "symbol": "TQQQ",
            "side": "buy",
            "type": "limit",
            "time_in_force": "day",
            "extended_hours": False,
            "status": "pending_replace",
            "qty": "2",
            "limit_price": "105",
            "filled_qty": "0",
            "replaced_by": "buy-leaf",
        }
        malformed_deterministic_order = {
            "id": "buy-malformed",
            "client_order_id": "rsi-buy-TQQQ-20260102",
            "status": "new",
        }
        fresh_clock = {
            "is_open": False,
            "timestamp": "2026-01-05T13:30:00Z",
            "next_open": "2026-01-05T14:30:00Z",
        }
        common_second_signal_preflight = [
            response(404, {}),
            response(200, []),
            asset_response("SQQQ", status="active", tradable=True),
            response(404, {}),
            response(200, fresh_clock),
            response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}]),
        ]
        cases = {
            "replacement transport failure": [
                response(200, deterministic_root),
                requests.Timeout("successor unavailable"),
                *common_second_signal_preflight,
            ],
            "malformed exact open-order payload": [
                response(404, {}),
                response(200, [malformed_deterministic_order], complete_orders=False),
                *common_second_signal_preflight,
            ],
        }
        signals = pd.DataFrame(
            [
                {"Asset": "TQQQ", "Date": "2026-01-02"},
                {"Asset": "SQQQ", "Date": "2026-01-02"},
            ]
        )

        for source, broker_responses in cases.items():
            with self.subTest(source=source):
                mock_get.reset_mock(side_effect=True)
                mock_post.reset_mock()
                mock_get.side_effect = broker_responses

                with self.assertRaises(AlpacaBuyBatchError) as raised:
                    submit_alpaca_paper_buy_orders(signals, self.cfg(buy=True))

                self.assertEqual(
                    raised.exception.results[["Asset", "Status"]].values.tolist(),
                    [["TQQQ", "error"], ["SQQQ", "batch_aborted"]],
                )
                self.assertTrue(raised.exception.broker_side_effects_possible)
                self.assertFalse(any(call.args[0].endswith("/v2/account") for call in mock_get.call_args_list))
                mock_post.assert_not_called()

