    @patch("leveraged_trader.alpaca.requests.post")
    def test_gtc_sell_quantity_must_be_an_exact_whole_share_before_submission(
        self,
        mock_post: Mock,
    ) -> None:
        client = AlpacaClient(self.cfg(sell=True))

        client.submit_limit_sell_order(
            symbol="TQQQ",
            qty=2,
            limit_price=150,
            client_order_id="sell-whole-quantity",
        )

        self.assertEqual(mock_post.call_args.kwargs["json"]["qty"], "2")
        self.assertEqual(mock_post.call_args.kwargs["json"]["position_intent"], "sell_to_close")

        for quantity in (1e-9, 1.123456789):
            with (
                self.subTest(quantity=quantity),
                self.assertRaisesRegex(
                    ValueError,
                    "whole-share value",
                ),
            ):
                client.submit_limit_sell_order(
                    symbol="TQQQ",
                    qty=quantity,
                    limit_price=150,
                    client_order_id="sell-invalid-quantity",
                )

        with self.assertRaisesRegex(ValueError, "9-decimal quantity precision"):
            client.submit_limit_sell_order(
                symbol="TQQQ",
                qty=1e-10,
                limit_price=150,
                client_order_id="sell-overprecise-quantity",
            )

        self.assertEqual(mock_post.call_count, 1)

