    def test_unresolved_ambiguous_http_buy_error_is_fatal_and_keeps_managed_intent_active(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        ambiguous_responses = (
            (409, {"message": "order submission conflict"}),
            (422, {"message": "client_order_id already exists"}),
        )
        for status_code, payload in ambiguous_responses:
            with self.subTest(status_code=status_code), closing(sqlite3.connect(":memory:")) as conn, conn:
                mock_get.reset_mock()
                mock_post.reset_mock()
                mock_get.side_effect = [
                    response(404, {}),
                    response(200, []),
                    asset_response("TQQQ", status="active", tradable=True),
                    response(404, {}),
                    response(
                        200,
                        {
                            "is_open": False,
                            "timestamp": "2026-01-05T13:30:00Z",
                            "next_open": "2026-01-05T14:30:00Z",
                        },
                    ),
                    response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}]),
                    response(200, {"cash": "3000"}),
                    *final_managed_buy_pre_submit_responses(),
                    response(404, {}),
                ]
                mock_post.return_value = error_response(status_code, payload)
                init_state_db(conn)

                with self.assertRaises(AlpacaBuyBatchError) as raised:
                    submit_alpaca_paper_buy_orders(
                        pd.DataFrame(
                            [
                                {
                                    "Asset": "TQQQ",
                                    "RSI Symbol": "QQQ",
                                    "Date": "2026-01-02",
                                    "Buy RSI": 30.0,
                                    "Sell Return Multiple": 1.5,
                                }
                            ]
                        ),
                        self.cfg(buy=True),
                        conn=conn,
                    )
                managed = load_alpaca_managed_positions(conn)

                self.assertEqual(raised.exception.results.loc[0, "Status"], "submission_unknown")
                self.assertTrue(raised.exception.broker_side_effects_possible)
                self.assertEqual(managed.loc[0, "buy_status"], "submission_unknown")
                self.assertTrue(pd.isna(managed.loc[0, "closed_at"]))

