    @patch("leveraged_trader.alpaca.requests.get")
    def test_reconciliation_rejects_stale_terminal_zero_fill_after_newer_active_buy(
        self,
        mock_get: Mock,
    ) -> None:
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            save_alpaca_managed_buy_order(
                conn,
                symbol="TQQQ",
                signal_symbol="QQQ",
                buy_rsi=30,
                profit_target_multiple=1.5,
                buy_signal_date="2026-01-02",
                buy_client_order_id="rsi-buy-TQQQ-20260102",
                buy_alpaca_order_id="buy-1",
                buy_submitted_at="2026-01-02T14:30:00Z",
                buy_status="accepted",
            )
            mock_get.return_value = response(
                200,
                {
                    "id": "buy-1",
                    "status": "new",
                    "submitted_at": "2026-01-02T14:30:00Z",
                    "updated_at": "2026-01-02T14:35:00Z",
                    "filled_qty": "0",
                },
            )
            current_result = reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
            current = load_alpaca_managed_positions(conn).iloc[0]

            mock_get.return_value = response(
                200,
                {
                    "id": "buy-1",
                    "status": "canceled",
                    "submitted_at": "2026-01-02T14:30:00Z",
                    "updated_at": "2026-01-02T14:34:00Z",
                    "filled_qty": "0",
                },
            )
            stale_result = reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
            after_stale = load_alpaca_managed_positions(conn).iloc[0]

        self.assertEqual(current_result.loc[0, "Status"], "new")
        self.assertEqual(current["buy_status"], "new")
        self.assertEqual(
            current["buy_observation_broker_updated_at"],
            "2026-01-02T14:35:00.000000Z",
        )
        self.assertEqual(stale_result.loc[0, "Status"], "superseded")
        self.assertEqual(after_stale["state_revision"], current["state_revision"])
        self.assertEqual(after_stale["buy_status"], "new")
        self.assertEqual(
            after_stale["buy_observation_broker_updated_at"],
            "2026-01-02T14:35:00.000000Z",
        )
        self.assertTrue(pd.isna(after_stale["closed_at"]))

