    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.delete")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_partial_managed_buy_replaces_sell_when_more_shares_fill(
        self,
        mock_get: Mock,
        mock_delete: Mock,
        mock_post: Mock,
    ) -> None:
        """A still-open parent buy keeps its protective sell sized to all fills."""
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            save_alpaca_managed_buy_order(
                conn,
                symbol="TQQQ",
                signal_symbol="QQQ",
                buy_rsi=30,
                profit_target_multiple=1.5,
                buy_signal_date="2026-01-02",
                buy_client_order_id="rsi-buy-TQQQ-20260102",
                buy_alpaca_order_id="buy-1",
                buy_submitted_at="2026-01-02T14:30:00Z",
                buy_status="accepted",
                buy_order_qty=3,
                buy_order_limit_price=105,
            )
            accepted_sell = {
                "id": "sell-1",
                "status": "accepted",
                "qty": "2",
                "filled_qty": "0",
                "limit_price": "150",
            }
            canceled_sell = {**accepted_sell, "status": "canceled"}
            mock_get.side_effect = [
                response(
                    200,
                    {
                        "id": "buy-1",
                        "status": "partially_filled",
                        "qty": "3",
                        "filled_qty": "2",
                        "filled_avg_price": "100",
                    },
                ),
                response(200, []),
                response(200, [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "2"}]),
                *final_managed_sell_pre_submit_responses(),
                response(
                    200,
                    {
                        "id": "buy-1",
                        "status": "partially_filled",
                        "qty": "3",
                        "filled_qty": "3",
                        "filled_avg_price": "101",
                        "updated_at": "2026-01-02T14:31:00Z",
                    },
                ),
                response(200, accepted_sell),
                response(200, [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "3"}]),
                response(200, canceled_sell),
                *final_managed_sell_pre_submit_responses(
                    qty=3,
                    historical_orders=(canceled_sell,),
                ),
            ]
            mock_delete.return_value = response(204, {}, complete_orders=False)
            mock_post.side_effect = [
                response(200, {"id": "sell-1", "status": "accepted"}),
                response(
                    200,
                    {
                        "id": "sell-2",
                        "client_order_id": "rsi-exit-TQQQ-1-r1",
                        "status": "accepted",
                        "qty": "3",
                        "limit_price": "151.5",
                    },
                ),
            ]

            reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
            result = reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
            managed = load_alpaca_managed_positions(conn)

        self.assertEqual(result["Status"].tolist(), ["partially_filled", "renewed"])
        self.assertEqual(mock_post.call_args_list[0].kwargs["json"]["qty"], "2")
        self.assertEqual(mock_post.call_args_list[1].kwargs["json"]["qty"], "3")
        self.assertEqual(mock_post.call_args_list[1].kwargs["json"]["limit_price"], "151.5")
        self.assertEqual(managed.loc[0, "target_sell_price"], 151.5)
        self.assertEqual(managed.loc[0, "sell_order_limit_price"], 151.5)
        self.assertEqual(managed.loc[0, "sell_alpaca_order_id"], "sell-2")
        mock_delete.assert_called_once()

    @patch("leveraged_trader.alpaca.requests.delete")
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_sell_observation_rejects_parent_fill_that_advances_after_buy_refresh(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
    ) -> None:
        buy_order = {
            "id": "buy-1",
            "status": "partially_filled",
            "qty": "3",
            "filled_qty": "2",
            "filled_avg_price": "100",
        }
        stale_sell_order = {
            "id": "sell-1",
            "status": "accepted",
            "qty": "2",
            "filled_qty": "0",
            "limit_price": "150",
            "expires_at": "2026-12-31T20:15:00Z",
        }
        interleaving: dict[str, object] = {}

        with tempfile.TemporaryDirectory() as tmpdir:
            db_path = Path(tmpdir) / "state.db"
            with (
                closing(sqlite3.connect(db_path)) as conn,
                conn,
                closing(sqlite3.connect(db_path)) as concurrent_conn,
                concurrent_conn,
            ):
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="partially_filled",
                    buy_order_qty=3,
                    buy_order_limit_price=105,
                )
                mark_alpaca_managed_buy_filled(
                    conn,
                    1,
                    buy_status="partially_filled",
                    filled_qty=2,
                    filled_avg_price=100,
                    filled_at=None,
                    target_sell_price=150,
                )
                record_alpaca_managed_sell_order(
                    conn,
                    1,
                    sell_client_order_id="rsi-exit-TQQQ-1",
                    sell_alpaca_order_id="sell-1",
                    sell_submitted_at="2026-01-02T14:32:00Z",
                    sell_status="new",
                    sell_expires_at="2026-12-31T20:15:00Z",
                    sell_order_qty=2,
                    sell_order_limit_price=150,
                )

                def get_response(url: str, **_kwargs: object) -> Mock:
                    if url.endswith("/v2/orders/buy-1"):
                        return response(200, buy_order)
                    if url.endswith("/v2/orders/sell-1"):
                        interleaving["parent_fill_applied"] = mark_alpaca_managed_buy_filled(
                            concurrent_conn,
                            1,
                            buy_status="partially_filled",
                            filled_qty=3,
                            filled_avg_price=101,
                            filled_at=None,
                            target_sell_price=151.5,
                            buy_alpaca_order_id="buy-1",
                            expected_buy_status="partially_filled",
                            expected_buy_alpaca_order_id="buy-1",
                            expected_filled_qty=2,
                            expected_filled_avg_price=100,
                            expected_target_sell_price=150,
                            expected_sell_client_order_id="rsi-exit-TQQQ-1",
                        )
                        return response(200, stale_sell_order)
                    raise AssertionError(f"unexpected Alpaca GET: {url}")

                mock_get.side_effect = get_response
                result = reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
                managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertTrue(interleaving["parent_fill_applied"])
        self.assertEqual(result["Status"].tolist(), ["partially_filled", "superseded"])
        self.assertEqual(managed["filled_qty"], 3)
        self.assertEqual(managed["filled_avg_price"], 101)
        self.assertEqual(managed["target_sell_price"], 151.5)
        self.assertEqual(managed["remaining_qty"], 3)
        self.assertEqual(managed["sell_status"], "new")
        self.assertEqual(managed["sell_alpaca_order_id"], "sell-1")
        mock_delete.assert_not_called()
        mock_post.assert_not_called()

