    @patch("leveraged_trader.alpaca.requests.get")
    def test_delayed_filled_sell_cannot_override_newer_partial_cancellation(
        self,
        mock_get: Mock,
    ) -> None:
        sell_client_order_id = "rsi-exit-TQQQ-1"
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_filled_managed_buy(conn)
            record_alpaca_managed_sell_order(
                conn,
                1,
                sell_client_order_id=sell_client_order_id,
                sell_alpaca_order_id="sell-1",
                sell_submitted_at="2026-01-02T14:32:00Z",
                sell_status="accepted",
                sell_order_qty=2,
                sell_order_limit_price=150,
            )
            self.assertTrue(
                update_alpaca_managed_sell_status_if_current(
                    conn,
                    1,
                    expected_sell_client_order_id=sell_client_order_id,
                    sell_status="canceled",
                    sell_alpaca_order_id="sell-1",
                    sell_broker_updated_at="2026-01-02T14:35:00Z",
                )
            )
            remaining_qty, observation_is_current = mark_alpaca_managed_sell_filled_if_current(
                conn,
                1,
                expected_sell_client_order_id=sell_client_order_id,
                sell_status="canceled",
                sell_filled_qty=1,
                sell_filled_avg_price=151,
                sell_filled_at="2026-01-02T14:34:00Z",
                sell_broker_updated_at="2026-01-02T14:35:00Z",
                sell_alpaca_order_id="sell-1",
            )
            before = conn.execute(
                "SELECT state_revision, sell_status, sell_filled_qty, sell_filled_avg_price, "
                "sell_filled_at, sold_qty, sold_value, remaining_qty, closed_at "
                "FROM alpaca_managed_positions WHERE id = 1"
            ).fetchone()
            mock_get.return_value = response(
                200,
                {
                    "id": "sell-1",
                    "client_order_id": sell_client_order_id,
                    "asset_id": "asset-tqqq",
                    "symbol": "TQQQ",
                    "side": "sell",
                    "status": "filled",
                    "submitted_at": "2026-01-02T14:32:00Z",
                    "updated_at": "2026-01-02T14:33:00Z",
                    "filled_at": "2026-01-02T14:33:00Z",
                    "qty": "2",
                    "limit_price": "150",
                    "filled_qty": "2",
                    "filled_avg_price": "150",
                },
            )

            with self.assertRaises(AlpacaReconciliationError) as raised:
                reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
            after = conn.execute(
                "SELECT state_revision, sell_status, sell_filled_qty, sell_filled_avg_price, "
                "sell_filled_at, sold_qty, sold_value, remaining_qty, closed_at "
                "FROM alpaca_managed_positions WHERE id = 1"
            ).fetchone()

        self.assertTrue(observation_is_current)
        self.assertEqual(remaining_qty, 1)
        self.assertEqual(after, before)
        self.assertEqual(after[1], "canceled")
        self.assertEqual(after[5:8], (1, 151, 1))
        self.assertIsNone(after[-1])
        self.assertEqual(raised.exception.results.iloc[-1]["Status"], "canceled")
        self.assertNotEqual(raised.exception.results.iloc[-1]["Status"], "quantity_mismatch")
        mock_get.assert_called_once()

