    def test_sell_submission_recovery_fences_and_cancels_wrong_position_intent(self) -> None:
        rows: list[dict] = []
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_missing_managed_sell_retry(conn)
            client = Mock()
            client.get_order_by_client_order_id.return_value = response(
                200,
                {
                    "id": "sell-wrong-intent",
                    "client_order_id": "rsi-exit-TQQQ-1",
                    "asset_id": "asset-tqqq",
                    "symbol": "TQQQ",
                    "side": "sell",
                    "position_intent": "sell_to_open",
                    "status": "partially_filled",
                    "qty": "2",
                    "filled_qty": "1",
                    "filled_avg_price": "160",
                    "limit_price": "150",
                },
            )
            durable_statuses: list[str] = []

            def cancel_after_durable_quarantine(order_id: str) -> Mock:
                self.assertEqual(order_id, "sell-wrong-intent")
                durable_statuses.append(
                    str(conn.execute("SELECT sell_status FROM alpaca_managed_positions WHERE id = 1").fetchone()[0])
                )
                return response(204, {}, complete_orders=False)

            client.cancel_order.side_effect = cancel_after_durable_quarantine
            recovered = _recover_managed_sell_submission(
                conn=conn,
                client=client,
                rows=rows,
                position_id=1,
                symbol="TQQQ",
                buy_client_order_id="rsi-buy-TQQQ-20260102",
                sell_client_order_id="rsi-exit-TQQQ-1",
                filled_qty=2,
                target_sell_price=150,
                message="submission response lost",
                close_on_complete=True,
                expected_alpaca_asset_id="asset-tqqq",
            )
            managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertTrue(recovered)
        self.assertEqual(rows[0]["Status"], "pending_cancel")
        self.assertIn("incompatible position intent", rows[0]["Message"])
        self.assertEqual(managed["sell_status"], "pending_cancel")
        self.assertEqual(managed["sell_alpaca_order_id"], "sell-wrong-intent")
        self.assertEqual(managed["sold_qty"], 0)
        self.assertEqual(managed["sold_value"], 0)
        self.assertTrue(pd.isna(managed["realized_pl"]))
        self.assertEqual(managed["remaining_qty"], 2)
        self.assertEqual(durable_statuses, ["pending_cancel"])
        client.cancel_order.assert_called_once_with("sell-wrong-intent")

