    def test_exact_pending_sell_cancellation_preempts_parent_buy_audit(self) -> None:
        sell_order = {
            "id": "sell-1",
            "client_order_id": "rsi-exit-TQQQ-1",
            "asset_id": "asset-tqqq",
            "symbol": "TQQQ",
            "side": "sell",
            "type": "limit",
            "time_in_force": "gtc",
            "extended_hours": False,
            "status": "accepted",
            "qty": "2",
            "filled_qty": "0",
            "limit_price": "150",
            "submitted_at": "2026-01-02T14:32:00Z",
            # Expiration is irrelevant to strict cancellation attribution and
            # must not starve a durable active-order fence.
            "expires_at": "not-a-timestamp",
        }
        client = Mock()
        durable_states_at_cancel: list[tuple[object, ...]] = []

        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_filled_managed_buy(conn)
            record_alpaca_managed_sell_order(
                conn,
                1,
                sell_client_order_id="rsi-exit-TQQQ-1",
                sell_alpaca_order_id="sell-1",
                sell_submitted_at="2026-01-02T14:32:00Z",
                sell_status="accepted",
                sell_order_qty=2,
                sell_order_limit_price=150,
            )
            update_alpaca_managed_sell_status(
                conn,
                1,
                sell_status="pending_cancel",
                sell_renewal_requested_at="2026-01-02T14:40:00Z",
            )

            def sell_lookup(order_id: str) -> requests.Response:
                self.assertEqual(order_id, "sell-1", "parent buy audit ran before the sell cancellation")
                return response(200, sell_order, complete_orders=False)

            def cancel_after_durable_fence(_order_id: str) -> requests.Response:
                durable_states_at_cancel.append(
                    conn.execute(
                        "SELECT sell_status, sell_renewal_requested_at FROM alpaca_managed_positions WHERE id = 1"
                    ).fetchone()
                )
                return response(204, {}, complete_orders=False)

            client.get_order.side_effect = sell_lookup
            client.cancel_order.side_effect = cancel_after_durable_fence
            with (
                patch(
                    "leveraged_trader.alpaca.AlpacaClient",
                    return_value=client,
                ),
                patch(
                    "leveraged_trader.alpaca._utc_now",
                    return_value=datetime(2026, 1, 3, tzinfo=UTC),
                ),
            ):
                for _ in range(2):
                    with self.assertRaises(AlpacaReconciliationError) as raised:
                        reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
                    self.assertEqual(raised.exception.results.loc[0, "Action"], "sell")
                    self.assertEqual(raised.exception.results.loc[0, "Status"], "pending_cancel")

                def sell_lookup_after_concurrent_terminal_update(order_id: str) -> requests.Response:
                    self.assertEqual(order_id, "sell-1")
                    update_alpaca_managed_sell_status(
                        conn,
                        1,
                        sell_status="canceled",
                        notes="concurrent terminal observation",
                    )
                    return response(200, sell_order, complete_orders=False)

                client.get_order.side_effect = sell_lookup_after_concurrent_terminal_update
                concurrent_result = reconcile_alpaca_managed_positions(
                    conn,
                    self.cfg(buy=True, sell=True),
                )

            parent = conn.execute(
                "SELECT sell_status, sell_alpaca_order_id, notes FROM alpaca_managed_positions WHERE id = 1"
            ).fetchone()

        self.assertEqual(concurrent_result.loc[0, "Status"], "superseded")
        self.assertEqual(parent, ("canceled", "sell-1", "concurrent terminal observation"))
        self.assertEqual(len(durable_states_at_cancel), 2)
        self.assertTrue(all(state[0] == "pending_cancel" and state[1] for state in durable_states_at_cancel))
        self.assertEqual(
            [call.args for call in client.get_order.call_args_list],
            [("sell-1",), ("sell-1",), ("sell-1",)],
        )
        self.assertEqual([call.args for call in client.cancel_order.call_args_list], [("sell-1",), ("sell-1",)])

