    @patch("leveraged_trader.alpaca.requests.get")
    def test_unattached_sell_wrong_position_intent_is_recovered_only_for_cancellation(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
    ) -> None:
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_filled_managed_buy(conn)
            mock_get.return_value = response(
                200,
                [
                    {
                        "id": "sell-wrong-intent",
                        "client_order_id": "rsi-exit-TQQQ-1",
                        "asset_id": "asset-tqqq",
                        "symbol": "TQQQ",
                        "side": "sell",
                        "position_intent": "sell_to_open",
                        "status": "partially_filled",
                        "qty": "2",
                        "filled_qty": "1",
                        "filled_avg_price": "160",
                        "limit_price": "150",
                    }
                ],
            )
            durable_statuses: list[str] = []

            def cancel_after_durable_quarantine(*_args: object, **_kwargs: object) -> Mock:
                durable_statuses.append(
                    str(conn.execute("SELECT sell_status FROM alpaca_managed_positions WHERE id = 1").fetchone()[0])
                )
                return response(204, {}, complete_orders=False)

            mock_delete.side_effect = cancel_after_durable_quarantine
            with self.assertRaises(AlpacaReconciliationError) as raised:
                reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
            managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertEqual(raised.exception.results.loc[0, "Status"], "pending_cancel")
        self.assertIn("incompatible position intent", raised.exception.results.loc[0, "Message"])
        self.assertEqual(managed["sell_status"], "pending_cancel")
        self.assertEqual(managed["sell_alpaca_order_id"], "sell-wrong-intent")
        self.assertEqual(managed["sold_qty"], 0)
        self.assertEqual(managed["sold_value"], 0)
        self.assertTrue(pd.isna(managed["realized_pl"]))
        self.assertEqual(managed["remaining_qty"], 2)
        self.assertEqual(durable_statuses, ["pending_cancel"])
        self.assertTrue(mock_delete.call_args.args[0].endswith("/v2/orders/sell-wrong-intent"))
        mock_post.assert_not_called()

