    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_expired_material_tiny_sell_fill_is_accounted_before_replacement(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        sell_filled_qty = 1e-9
        sell_filled_avg_price = 1.5e9
        remaining_qty = 1.0 - sell_filled_qty
        expired_sell = {
            "id": "sell-1",
            "client_order_id": "rsi-exit-TQQQ-1",
            "asset_id": "asset-tqqq",
            "symbol": "TQQQ",
            "side": "sell",
            "type": "limit",
            "time_in_force": "gtc",
            "extended_hours": False,
            "status": "expired",
            "qty": "1",
            "limit_price": "150",
            "filled_qty": str(sell_filled_qty),
            "filled_avg_price": str(sell_filled_avg_price),
            "submitted_at": "2026-01-02T14:32:00Z",
            "updated_at": "2026-01-02T14:33:00Z",
            "filled_at": "2026-01-02T14:33:00Z",
        }
        mock_get.side_effect = [
            response(200, expired_sell),
            response(
                200,
                [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": str(remaining_qty)}],
            ),
            *final_managed_sell_pre_submit_responses(
                qty=remaining_qty,
                historical_orders=(expired_sell,),
            ),
        ]

        with closing(sqlite3.connect(":memory:")) as conn:
            init_state_db(conn)
            self.seed_filled_managed_buy(conn, qty=1, target_sell_price=150)
            record_alpaca_managed_sell_order(
                conn,
                1,
                sell_client_order_id="rsi-exit-TQQQ-1",
                sell_alpaca_order_id="sell-1",
                sell_submitted_at="2026-01-02T14:32:00Z",
                sell_status="accepted",
                sell_order_qty=1,
                sell_order_limit_price=150,
            )

            with self.assertRaises(AlpacaReconciliationError) as raised:
                reconcile_alpaca_managed_positions(conn, self.cfg(sell=True))
            managed = load_alpaca_managed_positions(conn)
            ledger = conn.execute(
                "SELECT filled_qty, filled_value FROM alpaca_managed_sell_fills WHERE alpaca_order_id = 'sell-1'"
            ).fetchone()

        self.assertEqual(raised.exception.results["Status"].tolist(), ["fractional_qty"])
        self.assertEqual(managed.loc[0, "sold_qty"], sell_filled_qty)
        self.assertAlmostEqual(managed.loc[0, "sold_value"], 1.5)
        self.assertEqual(managed.loc[0, "remaining_qty"], remaining_qty)
        self.assertEqual(ledger[0], sell_filled_qty)
        self.assertAlmostEqual(ledger[1], 1.5)
        self.assertEqual(mock_get.call_count, 2)
        mock_post.assert_not_called()

