    @patch("leveraged_trader.alpaca.requests.get")
    def test_post_refresh_parent_fill_prevents_stale_intent_cancellation(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
        mock_utc_now: Mock,
    ) -> None:
        mock_utc_now.return_value = datetime(2026, 3, 25, 14, 32, tzinfo=UTC)
        accepted_sell = {
            "id": "sell-1",
            "client_order_id": "rsi-exit-TQQQ-1",
            "status": "accepted",
            "submitted_at": "2026-01-02T14:32:00Z",
            "expires_at": "2026-06-30T20:15:00Z",
            "qty": "1",
            "filled_qty": "0",
            "limit_price": "150",
        }
        replaced_sell = {
            **accepted_sell,
            "status": "replaced",
            "replaced_by": "sell-worker-b-successor",
        }
        now_adequate_successor = {
            "id": "sell-worker-b-successor",
            "client_order_id": "worker-b-replacement",
            "status": "accepted",
            "replaces": "sell-1",
            "submitted_at": "2026-03-25T14:32:00Z",
            "expires_at": "2026-06-30T20:15:00Z",
            "qty": "3",
            "filled_qty": "0",
            "limit_price": "150",
        }
        interleaving: dict[str, object] = {}

        with tempfile.TemporaryDirectory() as tmpdir:
            db_path = Path(tmpdir) / "state.db"
            with (
                closing(sqlite3.connect(db_path)) as conn,
                conn,
                closing(sqlite3.connect(db_path)) as worker_b_conn,
                worker_b_conn,
            ):
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    alpaca_asset_id="asset-tqqq",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="filled",
                    buy_order_qty=3,
                )
                mark_alpaca_managed_buy_filled(
                    conn,
                    1,
                    buy_status="filled",
                    filled_qty=2,
                    filled_avg_price=100,
                    filled_at="2026-01-02T14:31:00Z",
                    target_sell_price=150,
                )
                record_alpaca_managed_sell_order(
                    conn,
                    1,
                    sell_client_order_id="rsi-exit-TQQQ-1",
                    sell_alpaca_order_id="sell-1",
                    sell_submitted_at="2026-01-02T14:32:00Z",
                    sell_status="accepted",
                    sell_expires_at="2026-06-30T20:15:00Z",
                    sell_order_qty=1,
                    sell_order_limit_price=150,
                )
                mock_get.side_effect = [
                    response(200, accepted_sell),
                    response(200, [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "2"}]),
                    response(200, replaced_sell),
                    response(200, now_adequate_successor),
                ]
                mock_delete.return_value = response(204, {}, complete_orders=False)

                def record_then_advance_parent(**kwargs: object) -> tuple[float, bool]:
                    result = _record_replacement_chain_sell_fills(**kwargs)
                    renewal_snapshot = kwargs.get("expected_renewal_snapshot")
                    if renewal_snapshot is None or getattr(renewal_snapshot, "requested_at", None) is None:
                        return result
                    interleaving["parent_fill_applied"] = mark_alpaca_managed_buy_filled(
                        worker_b_conn,
                        1,
                        buy_status="filled",
                        filled_qty=3,
                        filled_avg_price=100,
                        filled_at="2026-03-25T14:39:00Z",
                        target_sell_price=150,
                        buy_alpaca_order_id="buy-1",
                        expected_buy_status="filled",
                        expected_buy_alpaca_order_id="buy-1",
                        expected_filled_qty=2,
                        expected_filled_avg_price=100,
                        expected_target_sell_price=150,
                        expected_sell_client_order_id="rsi-exit-TQQQ-1",
                    )
                    return result

                with patch(
                    "leveraged_trader.alpaca._record_replacement_chain_sell_fills",
                    side_effect=record_then_advance_parent,
                ):
                    result = reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
                managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertTrue(interleaving["parent_fill_applied"])
        self.assertEqual(result.loc[0, "Status"], "superseded")
        self.assertEqual(managed["filled_qty"], 3)
        self.assertEqual(managed["remaining_qty"], 3)
        self.assertEqual(managed["sell_status"], "accepted")
        self.assertEqual(managed["sell_alpaca_order_id"], "sell-worker-b-successor")
        self.assertEqual(managed["sell_renewal_requested_at"], "2026-03-25T14:32:00Z")
        self.assertEqual(
            managed["notes"],
            "managed GTC sell replacement requested after managed buy fill changed",
        )
        self.assertEqual(mock_delete.call_count, 1)
        self.assertTrue(mock_delete.call_args.args[0].endswith("/v2/orders/sell-1"))
        mock_post.assert_not_called()

    @patch("leveraged_trader.alpaca._utc_now")
    @patch("leveraged_trader.alpaca.requests.delete")
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_renewal_claim_rejects_parent_fill_after_sell_observation(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
        mock_utc_now: Mock,
    ) -> None:
        mock_utc_now.return_value = datetime(2026, 3, 25, 14, 32, tzinfo=UTC)
        accepted_sell = {
            "id": "sell-1",
            "client_order_id": "rsi-exit-TQQQ-1",
            "status": "accepted",
            "submitted_at": "2026-01-02T14:32:00Z",
            "expires_at": "2026-06-30T20:15:00Z",
            "qty": "1",
            "filled_qty": "0",
            "limit_price": "150",
        }
        interleaving: dict[str, object] = {}

        with tempfile.TemporaryDirectory() as tmpdir:
            db_path = Path(tmpdir) / "state.db"
            with (
                closing(sqlite3.connect(db_path)) as conn,
                conn,
                closing(sqlite3.connect(db_path)) as concurrent_conn,
                concurrent_conn,
            ):
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    alpaca_asset_id="asset-tqqq",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="filled",
                    buy_order_qty=3,
                )
                mark_alpaca_managed_buy_filled(
                    conn,
                    1,
                    buy_status="filled",
                    filled_qty=2,
                    filled_avg_price=100,
                    filled_at="2026-01-02T14:31:00Z",
                    target_sell_price=150,
                )
                record_alpaca_managed_sell_order(
                    conn,
                    1,
                    sell_client_order_id="rsi-exit-TQQQ-1",
                    sell_alpaca_order_id="sell-1",
                    sell_submitted_at="2026-01-02T14:32:00Z",
                    sell_status="accepted",
                    sell_expires_at="2026-06-30T20:15:00Z",
                    sell_order_qty=1,
                    sell_order_limit_price=150,
                )

                def get_response(url: str, **_kwargs: object) -> Mock:
                    if url.endswith("/v2/orders/sell-1"):
                        return response(200, accepted_sell)
                    if url.endswith("/v2/positions"):
                        interleaving["parent_fill_applied"] = mark_alpaca_managed_buy_filled(
                            concurrent_conn,
                            1,
                            buy_status="filled",
                            filled_qty=3,
                            filled_avg_price=100,
                            filled_at="2026-03-25T14:31:00Z",
                            target_sell_price=150,
                            buy_alpaca_order_id="buy-1",
                            expected_buy_status="filled",
                            expected_buy_alpaca_order_id="buy-1",
                            expected_filled_qty=2,
                            expected_filled_avg_price=100,
                            expected_target_sell_price=150,
                            expected_sell_client_order_id="rsi-exit-TQQQ-1",
                        )
                        # The broker position endpoint can lag the concurrent
                        # cumulative-fill correction; the local claim must
                        # still reject the obsolete two-share snapshot.
                        return response(
                            200,
                            [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "2"}],
                        )
                    raise AssertionError(f"unexpected Alpaca GET: {url}")

                mock_get.side_effect = get_response
                result = reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
                managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertTrue(interleaving["parent_fill_applied"])
        self.assertEqual(result.loc[0, "Status"], "superseded")
        self.assertIn("quantity, target, or lease changed", result.loc[0, "Message"])
        self.assertEqual(managed["filled_qty"], 3)
        self.assertEqual(managed["remaining_qty"], 3)
        self.assertEqual(managed["sell_status"], "accepted")
        self.assertTrue(pd.isna(managed["sell_renewal_requested_at"]))
        mock_delete.assert_not_called()
        mock_post.assert_not_called()

