    def test_buy_batch_error_infers_possible_broker_side_effects_from_results(self) -> None:
        for status in ("submitted", "submission_unknown", "incomplete_fill_metadata", "superseded"):
            with self.subTest(status=status):
                error = AlpacaBuyBatchError("batch failed", pd.DataFrame([{"Status": status}]))
                self.assertTrue(error.broker_side_effects_possible)

        error = AlpacaBuyBatchError("phase-one failure", pd.DataFrame([{"Status": "error"}]))
        self.assertFalse(error.broker_side_effects_possible)

