    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_unattached_open_sell_requires_exact_limit_gtc_regular_hours_identity(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        invalid_fields = [
            {"type": "market"},
            {"time_in_force": "day"},
            {"extended_hours": True},
            {"asset_id": "wrong-asset"},
        ]
        for invalid in invalid_fields:
            with self.subTest(invalid=invalid), closing(sqlite3.connect(":memory:")) as conn, conn:
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="filled",
                )
                mark_alpaca_managed_buy_filled(
                    conn,
                    1,
                    buy_status="filled",
                    filled_qty=2,
                    filled_avg_price=100,
                    filled_at="2026-01-02T14:31:00Z",
                    target_sell_price=150,
                )
                if "asset_id" in invalid:
                    conn.execute("UPDATE alpaca_managed_positions SET alpaca_asset_id = 'expected-asset'")
                    conn.commit()
                candidate = {
                    "id": "sell-wrong",
                    "asset_id": "expected-asset",
                    "symbol": "TQQQ",
                    "side": "sell",
                    "type": "limit",
                    "time_in_force": "gtc",
                    "extended_hours": False,
                    "client_order_id": "rsi-exit-TQQQ-1",
                    "status": "accepted",
                    "qty": "2",
                    "limit_price": "150",
                }
                candidate.update(invalid)
                mock_get.reset_mock()
                mock_post.reset_mock()
                mock_get.side_effect = [response(200, [candidate]), response(200, [])]

                with self.assertRaises(AlpacaReconciliationError) as raised:
                    reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
                result = raised.exception.results
                managed = load_alpaca_managed_positions(conn)

                expected_status = "position_quantity_mismatch" if "asset_id" in invalid else "open_order"
                self.assertEqual(result.loc[0, "Status"], expected_status)
                self.assertTrue(pd.isna(managed.loc[0, "sell_client_order_id"]))
                self.assertTrue(pd.isna(managed.loc[0, "sell_alpaca_order_id"]))
                mock_post.assert_not_called()

