    @patch("leveraged_trader.alpaca._latest_market_price", return_value=100.0)
    def test_hostile_credential_exception_aborts_preflight_without_calling_str(
        self,
        _mock_latest_price: Mock,
        mock_client_factory: Mock,
    ) -> None:
        class HostileCredentialError(ValueError):
            str_calls = 0

            def __str__(self) -> str:
                type(self).str_calls += 1
                raise AssertionError("credential exception __str__ must not be called")

        client = mock_client_factory.return_value
        client.get_order_by_client_order_id.side_effect = [
            response(404, {}),
            HostileCredentialError("Alpaca placeholder credential validation failed"),
        ]
        client.open_orders.return_value = []
        client.asset.return_value = {
            "id": "asset-tqqq",
            "class": "us_equity",
            "symbol": "TQQQ",
            "tradable": True,
            "status": "active",
        }
        client.position_qty.return_value = 0.0
        client.market_clock.return_value = {
            "is_open": False,
            "timestamp": "2026-01-05T13:30:00Z",
            "next_open": "2026-01-05T14:30:00Z",
        }
        client.calendar.return_value = [{"date": "2026-01-02"}, {"date": "2026-01-05"}]

        with self.assertRaises(AlpacaBuyBatchError) as raised:
            submit_alpaca_paper_buy_orders(
                pd.DataFrame(
                    [
                        {"Asset": "TQQQ", "Date": "2026-01-02"},
                        {"Asset": "SQQQ", "Date": "2026-01-02"},
                    ]
                ),
                self.cfg(buy=True),
            )

        self.assertEqual(
            raised.exception.results[["Asset", "Status"]].values.tolist(),
            [["TQQQ", "batch_aborted"], ["SQQQ", "error"]],
        )
        self.assertIn("placeholder credential", raised.exception.results.loc[1, "Message"])
        self.assertEqual(HostileCredentialError.str_calls, 0)
        client.submit_limit_buy_order.assert_not_called()

