    def test_submission_fatal_identity_result_aborts_later_orders(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        def get_response(url: str, **kwargs: object) -> Mock:
            if "/v2/orders:by_client_order_id" in url:
                return response(404, {})
            if url.endswith("/v2/orders"):
                return response(200, [])
            if "/v2/assets/" in url:
                return asset_response(url.rsplit("/", 1)[-1], status="active", tradable=True)
            if "/v2/positions/" in url:
                return response(404, {})
            if url.endswith("/v2/clock"):
                return response(
                    200,
                    {
                        "is_open": False,
                        "timestamp": "2026-01-05T13:30:00Z",
                        "next_open": "2026-01-05T14:30:00Z",
                    },
                )
            if url.endswith("/v2/calendar"):
                return response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}])
            if url.endswith("/v2/account"):
                return response(200, {"cash": "9000"})
            raise AssertionError(f"unexpected Alpaca GET: {url}; {kwargs}")

        def post_response(_url: str, **kwargs: object) -> Mock:
            payload = dict(kwargs["json"])
            if payload["symbol"] == "asset-sqqq":
                payload.update({"id": "wrong-order", "symbol": "AAPL", "side": "sell"})
            else:
                payload.update(
                    {
                        "id": "buy-tqqq",
                        "asset_id": "asset-tqqq",
                        "symbol": "TQQQ",
                        "status": "accepted",
                    }
                )
            return response(200, payload)

        mock_get.side_effect = get_response
        mock_post.side_effect = post_response

        with self.assertRaises(AlpacaBuyBatchError) as raised:
            submit_alpaca_paper_buy_orders(
                pd.DataFrame(
                    [
                        {"Asset": "TQQQ", "Date": "2026-01-02"},
                        {"Asset": "SQQQ", "Date": "2026-01-02"},
                        {"Asset": "UPRO", "Date": "2026-01-02"},
                    ]
                ),
                self.cfg(buy=True),
            )

        result = raised.exception.results
        self.assertEqual(result["Status"].tolist(), ["submitted", "identity_mismatch", "batch_aborted"])
        self.assertTrue(raised.exception.broker_side_effects_possible)
        self.assertEqual(mock_post.call_count, 2)
        self.assertEqual(
            [call.kwargs["json"]["symbol"] for call in mock_post.call_args_list],
            ["asset-tqqq", "asset-sqqq"],
        )

