    @patch("leveraged_trader.alpaca.requests.get")
    def test_reconciliation_quarantines_mutated_terminal_sell_successor_intent(
        self,
        mock_get: Mock,
    ) -> None:
        mutated_successors = {
            "price": {"qty": "1", "limit_price": "1", "filled_qty": "1"},
            "quantity": {"qty": "2", "limit_price": "150", "filled_qty": "1"},
        }
        for mutation, changed_fields in mutated_successors.items():
            with self.subTest(mutation=mutation), closing(sqlite3.connect(":memory:")) as conn, conn:
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="filled",
                )
                mark_alpaca_managed_buy_filled(
                    conn,
                    1,
                    buy_status="filled",
                    filled_qty=2,
                    filled_avg_price=100,
                    filled_at="2026-01-02T14:31:00Z",
                    target_sell_price=150,
                )
                record_alpaca_managed_sell_order(
                    conn,
                    1,
                    sell_client_order_id="rsi-exit-TQQQ-1",
                    sell_alpaca_order_id="sell-root",
                    sell_submitted_at="2026-01-02T14:32:00Z",
                    sell_status="accepted",
                    sell_order_qty=2,
                )
                mock_get.side_effect = [
                    response(
                        200,
                        {
                            "id": "sell-root",
                            "client_order_id": "rsi-exit-TQQQ-1",
                            "status": "replaced",
                            "replaced_by": "sell-leaf",
                            "qty": "2",
                            "limit_price": "150",
                            "filled_qty": "1",
                            "filled_avg_price": "150",
                        },
                    ),
                    response(
                        200,
                        {
                            "id": "sell-leaf",
                            "client_order_id": "manual-sell-replacement",
                            "status": "filled",
                            "replaces": "sell-root",
                            "filled_at": "2026-01-03T15:00:00Z",
                            "filled_avg_price": changed_fields["limit_price"],
                            **changed_fields,
                        },
                    ),
                ]

                with self.assertRaises(AlpacaReconciliationError) as raised:
                    reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
                result = raised.exception.results
                managed = load_alpaca_managed_positions(conn)

                self.assertEqual(result.loc[0, "Status"], "quantity_mismatch")
                self.assertIn("replacement generation 1", result.loc[0, "Message"])
                self.assertEqual(managed.loc[0, "sell_status"], "quantity_mismatch")
                self.assertEqual(managed.loc[0, "sell_order_qty"], 2.0)
                self.assertEqual(managed.loc[0, "sell_order_limit_price"], 150.0)
                self.assertEqual(managed.loc[0, "sold_qty"], 2.0)
                self.assertEqual(managed.loc[0, "remaining_qty"], 0.0)
                self.assertTrue(pd.isna(managed.loc[0, "closed_at"]))

