    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_configured_credential_is_redacted_from_reconciliation_and_notes(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        secret = "plainopaquecredential123456789"
        cfg = AlpacaOrderConfig(
            enabled=True,
            sell_enabled=True,
            api_key_id="key-id",
            api_secret_key=f" {secret} ",
        )
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_filled_managed_buy(conn)
            mock_get.side_effect = [
                response(200, []),
                response(200, [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "2"}]),
                *final_managed_sell_pre_submit_responses(),
            ]
            mock_post.return_value = error_response(403, {"message": secret})

            with self.assertRaises(AlpacaReconciliationError) as raised:
                reconcile_alpaca_managed_positions(conn, cfg)
            managed = load_alpaca_managed_positions(conn)

        public_diagnostic = str(raised.exception) + raised.exception.results.to_string()
