    @patch("leveraged_trader.alpaca.requests.post")
    def test_wrong_buy_position_intent_positive_fill_is_never_managed_long_accounting(
        self,
        mock_post: Mock,
        mock_get: Mock,
        mock_delete: Mock,
    ) -> None:
        for broker_status, filled_qty, expected_status, should_cancel in (
            ("partially_filled", "1", "pending_cancel", True),
            ("filled", "2", "identity_mismatch", False),
        ):
            with self.subTest(broker_status=broker_status), closing(sqlite3.connect(":memory:")) as conn, conn:
                mock_get.reset_mock()
                mock_delete.reset_mock()
                mock_post.reset_mock()
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    alpaca_asset_id="asset-tqqq",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="accepted",
                    buy_order_qty=2,
                    buy_order_limit_price=105,
                )
                wrong_intent_buy = {
                    "id": "buy-1",
                    "client_order_id": "rsi-buy-TQQQ-20260102",
                    "asset_id": "asset-tqqq",
                    "symbol": "TQQQ",
                    "side": "buy",
                    "position_intent": "buy_to_close",
                    "status": broker_status,
                    "qty": "2",
                    "limit_price": "105",
                    "filled_qty": filled_qty,
                    "filled_avg_price": "100",
                    "filled_at": "2026-01-02T14:31:00Z",
                }
                mock_get.return_value = response(200, wrong_intent_buy)
                cancellation_snapshots: list[tuple[str, object, object]] = []

                def cancel_after_quarantine(
                    *_args: object,
                    snapshots: list[tuple[str, object, object]] = cancellation_snapshots,
                    observed_conn: sqlite3.Connection = conn,
                    **_kwargs: object,
                ) -> Mock:
                    snapshots.append(
                        observed_conn.execute(
                            "SELECT buy_status, filled_qty, target_sell_price "
                            "FROM alpaca_managed_positions WHERE id = 1"
                        ).fetchone()
                    )
                    return response(204, {}, complete_orders=False)

                mock_delete.side_effect = cancel_after_quarantine
                with self.assertRaises(AlpacaReconciliationError) as raised:
                    reconcile_alpaca_managed_positions(
                        conn,
                        self.cfg(buy=True, sell=True),
                    )
                managed = load_alpaca_managed_positions(conn).iloc[0]

                self.assertEqual(raised.exception.results.loc[0, "Status"], expected_status)
                self.assertIn(
                    "excluded from managed-long accounting",
                    raised.exception.results.loc[0, "Message"],
                )
                self.assertEqual(managed["buy_status"], expected_status)
                self.assertTrue(pd.isna(managed["filled_qty"]))
                self.assertTrue(pd.isna(managed["filled_avg_price"]))
                self.assertTrue(pd.isna(managed["target_sell_price"]))
                self.assertTrue(pd.isna(managed["remaining_qty"]))
                self.assertTrue(pd.isna(managed["sell_client_order_id"]))
                self.assertEqual(
                    cancellation_snapshots,
                    [("pending_cancel", None, None)] if should_cancel else [],
                )
                self.assertEqual(mock_delete.call_count, int(should_cancel))
                mock_post.assert_not_called()

