        self.assertEqual(durable_ids_when_canceled, ['["buy-leaf","buy-root"]'] * 2)
        self.assertEqual(
            [call.args[0].rsplit("/", 1)[-1] for call in mock_delete.call_args_list],
            ["buy-root", "buy-leaf"],
        )

