    def test_filled_buy_without_positive_fill_metadata_is_quarantined(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        for buy_status, filled_qty in (("filled", "0"), ("partially_filled", None)):
            with self.subTest(buy_status=buy_status), closing(sqlite3.connect(":memory:")) as conn, conn:
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="accepted",
                )
                payload = {
                    "id": "buy-1",
                    "status": buy_status,
                    "submitted_at": "2026-01-02T14:30:00Z",
                }
                if filled_qty is not None:
                    payload["filled_qty"] = filled_qty
                mock_get.reset_mock()
                mock_post.reset_mock()
                mock_get.return_value = response(200, payload)

