                self.assertEqual(managed.loc[0, "buy_status"], "incomplete_fill_metadata")
                self.assertTrue(pd.isna(managed.loc[0, "filled_qty"]))
                self.assertTrue(pd.isna(managed.loc[0, "closed_at"]))
                mock_post.assert_not_called()

