    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_immediate_terminal_buy_leaf_preserves_ancestor_fill_and_lineage(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
        mock_utc_now: Mock,
    ) -> None:
        mock_utc_now.return_value = datetime(2026, 1, 5, tzinfo=UTC)
        buy_root = {
            "id": "buy-root",
            "client_order_id": "rsi-buy-TQQQ-20260102",
            "status": "replaced",
            "replaced_by": "buy-terminal-leaf",
            "qty": "1",
            "limit_price": "105",
            "filled_qty": "1",
            "filled_avg_price": "100",
            "filled_at": "2026-01-05T15:00:00Z",
        }
        buy_leaf = {
            "id": "buy-terminal-leaf",
            "client_order_id": "broker-buy-replacement",
            "status": "canceled",
            "replaces": "buy-root",
            "qty": "1",
            "limit_price": "105",
            "filled_qty": "0",
            "updated_at": "2026-01-05T15:01:00Z",
        }
        mock_get.side_effect = [
            response(404, {}),
            response(200, []),
            asset_response("TQQQ", status="active", tradable=True),
            response(404, {}),
            response(
                200,
                {
                    "is_open": False,
                    "timestamp": "2026-01-05T13:30:00Z",
                    "next_open": "2026-01-05T14:30:00Z",
                },
            ),
            response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}]),
            response(200, {"cash": "3000"}),
            *final_managed_buy_pre_submit_responses(),
            response(200, buy_leaf),
        ]
        mock_post.return_value = response(200, buy_root)

        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            submission = submit_alpaca_paper_buy_orders(
                pd.DataFrame(
                    [
                        {
                            "Asset": "TQQQ",
                            "RSI Symbol": "QQQ",
                            "Date": "2026-01-02",
                            "Buy RSI": 30.0,
                            "Sell Return Multiple": 1.5,
                        }
                    ]
                ),
                self.cfg(buy=True),
                conn=conn,
            )
            managed = load_alpaca_managed_positions(conn).iloc[0]
            sell_client_order_id = _alpaca_exit_client_order_id(
                "TQQQ",
                1,
                order_namespace=str(managed["sell_order_namespace"]),
            )

            mock_get.side_effect = [
                response(200, buy_leaf),
                response(200, buy_root),
                response(200, []),
                response(200, [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "1"}]),
                *final_managed_sell_pre_submit_responses(qty=1),
            ]
            mock_post.return_value = response(
                200,
                {
                    "id": "sell-protection",
                    "client_order_id": sell_client_order_id,
                    "status": "accepted",
                    "qty": "1",
                    "limit_price": "150",
                    "expires_at": "2027-06-23T20:15:00Z",
                },
            )
            reconciliation = reconcile_alpaca_managed_positions(
                conn,
                self.cfg(buy=True, sell=True),
            )
            protected = load_alpaca_managed_positions(conn).iloc[0]

        self.assertEqual(submission.loc[0, "Status"], "partially_filled")
        self.assertEqual(managed["buy_status"], "canceled")
        self.assertEqual(managed["buy_alpaca_order_id"], "buy-terminal-leaf")
        self.assertEqual(managed["filled_qty"], 1)
        self.assertEqual(managed["filled_avg_price"], 100)
        self.assertTrue(pd.isna(managed["closed_at"]))
        self.assertIn("accepted", reconciliation["Status"].tolist())
        self.assertEqual(protected["sell_status"], "accepted")
        self.assertEqual(protected["sell_alpaca_order_id"], "sell-protection")

