    @patch("leveraged_trader.alpaca._latest_market_price", return_value=100.0)
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    @patch("leveraged_trader.alpaca.active_alpaca_managed_symbols", return_value=set())
    def test_non_owner_incomplete_buy_recovery_losing_revision_fence_does_not_quarantine(
        self,
        _mock_managed_symbols: Mock,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        mock_get.side_effect = [
            response(404, {}),
            response(200, []),
            asset_response("TQQQ", status="active", tradable=True),
            response(404, {}),
            response(
                200,
                {"is_open": False, "timestamp": "2026-01-05T13:30:00Z", "next_open": "2026-01-05T14:30:00Z"},
            ),
            response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}]),
            response(200, {"cash": "3000"}),
            response(
                200,
                {
                    "id": "buy-concurrent-incomplete",
                    "client_order_id": "rsi-buy-TQQQ-20260102",
                    "asset_id": "asset-tqqq",
                    "symbol": "TQQQ",
                    "side": "buy",
                    "type": "limit",
                    "time_in_force": "day",
                    "extended_hours": False,
                    "status": "partially_filled",
                    "qty": "1",
                    "limit_price": "105",
                },
            ),
        ]

        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            claim = claim_alpaca_managed_buy_intent(
                conn,
                symbol="TQQQ",
                alpaca_asset_id="asset-tqqq",
                signal_symbol="QQQ",
                buy_rsi=30,
                profit_target_multiple=1.5,
                buy_signal_date="2026-01-02",
                buy_client_order_id="rsi-buy-TQQQ-20260102",
                buy_order_qty=1,
                buy_order_limit_price=105,
            )
            confirmed_revision: int | None = None

            def advance_owner_revision(*args: object, **kwargs: object) -> str | None:
                nonlocal confirmed_revision
                issue = _buy_replacement_chain_fill_metadata_issue(*args, **kwargs)
                if confirmed_revision is None:
                    confirmed_revision = confirm_alpaca_managed_buy_submission(
                        conn,
                        claim.position_id,
                        expected_buy_submission_attempt_count=claim.attempt_count,
                        expected_state_revision=claim.state_revision,
                        expected_buy_order_qty=1,
                        expected_buy_order_limit_price=105,
                        claimed_at="2026-01-05T13:31:00Z",
                    )
                return issue

            with (
                patch(
                    "leveraged_trader.alpaca._buy_replacement_chain_fill_metadata_issue",
                    side_effect=advance_owner_revision,
                ),
                patch(
                    "leveraged_trader.alpaca._append_accepted_buy_processing_failure",
                    return_value="stale incomplete-metadata recovery lost its revision fence",
                ) as processing_failure,
                self.assertRaises(AlpacaBuyBatchError),
            ):
                submit_alpaca_paper_buy_orders(
                    pd.DataFrame(
                        [
                            {
                                "Asset": "TQQQ",
                                "RSI Symbol": "QQQ",
                                "Date": "2026-01-02",
                                "Buy RSI": 30.0,
                                "Sell Return Multiple": 1.5,
                            }
                        ]
                    ),
                    self.cfg(buy=True),
                    conn=conn,
                )
            managed = conn.execute(
                "SELECT state_revision, buy_submission_claimed_at, buy_status, "
                "buy_alpaca_order_id, filled_qty, notes FROM alpaca_managed_positions WHERE id = ?",
                (claim.position_id,),
            ).fetchone()

        self.assertEqual(confirmed_revision, claim.state_revision + 1)
        self.assertEqual(
            managed,
            (
                confirmed_revision,
                "2026-01-05T13:31:00Z",
                "submission_pending",
                None,
                None,
                "managed buy submission generation re-fenced immediately before broker request",
            ),
        )
        self.assertIn("lost its persistence race", processing_failure.call_args.kwargs["detail"])
        mock_post.assert_not_called()

