    def test_replacement_chain_requires_fill_metadata_on_each_fill_claiming_node(self) -> None:
        invalid = _replacement_chain_fill_metadata(
            [
                {"id": "buy-1", "status": "filled", "filled_qty": "1", "filled_avg_price": "100"},
                {"id": "buy-2", "status": "partially_filled", "filled_qty": "0"},
            ]
        )
        valid_terminal_zero = _replacement_chain_fill_metadata(
            [
                {"id": "buy-1", "status": "filled", "filled_qty": "1", "filled_avg_price": "100"},
                {"id": "buy-2", "status": "canceled", "filled_qty": "0"},
            ]
        )

        self.assertEqual(invalid, (0.0, None, False))
        self.assertEqual(valid_terminal_zero, (1.0, 100.0, True))

