    def test_duplicate_accepted_buys_are_quarantined_before_cleanup(self) -> None:
        duplicate_orders = [
            _complete_order_fixture(
                {
                    "id": order_id,
                    "client_order_id": "rsi-buy-TQQQ-20260102",
                    "status": "accepted",
                    "qty": "2",
                    "filled_qty": "0",
                    "limit_price": "105",
                }
            )
            for order_id in ("buy-duplicate-1", "buy-duplicate-2")
        ]
        rows: list[dict] = []
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            save_alpaca_managed_buy_order(
                conn,
                symbol="TQQQ",
                alpaca_asset_id="asset-tqqq",
                signal_symbol="QQQ",
                buy_rsi=30,
                profit_target_multiple=1.5,
                buy_signal_date="2026-01-02",
                buy_client_order_id="rsi-buy-TQQQ-20260102",
                buy_alpaca_order_id=None,
                buy_submitted_at=None,
                buy_status="submission_pending",
                buy_order_qty=2,
                buy_order_limit_price=105,
            )
            statuses_when_canceled: list[str] = []
            client = Mock()

            def cancel_after_durable_quarantine(*_args: object, **_kwargs: object) -> Mock:
                statuses_when_canceled.append(
                    str(conn.execute("SELECT buy_status FROM alpaca_managed_positions WHERE id = 1").fetchone()[0])
                )
                return response(204, {}, complete_orders=False)

            client.cancel_order.side_effect = cancel_after_durable_quarantine
            _append_accepted_buy_processing_failure(
                conn=conn,
                client=client,
                rows=rows,
                workflow="rsi",
                signal_index=0,
                symbol="TQQQ",
                signal_date="2026-01-02",
                client_order_id="rsi-buy-TQQQ-20260102",
                notional=210,
                qty=2,
                limit_price=105,
                managed_position_id=1,
                managed_submission_attempt_count=1,
                accepted_response_payload=None,
                expected_alpaca_asset_id="asset-tqqq",
                additional_accepted_payloads=duplicate_orders,
                detail="duplicate deterministic orders",
            )
            durable = conn.execute(
                "SELECT buy_status, buy_alpaca_order_id, "
                "buy_cancellation_alpaca_order_ids "
                "FROM alpaca_managed_positions WHERE id = 1"
            ).fetchone()

        self.assertEqual(
            durable,
            (
                "pending_cancel",
                None,
                '["buy-duplicate-1","buy-duplicate-2"]',
            ),
        )
        self.assertEqual(statuses_when_canceled, ["pending_cancel", "pending_cancel"])
        self.assertEqual(
            [call.args[0] for call in client.cancel_order.call_args_list],
            ["buy-duplicate-1", "buy-duplicate-2"],
        )

