    @patch("leveraged_trader.alpaca.run_yfinance_ticker_history_with_deadline")
    def test_latest_market_price_uses_absolute_deadline_worker(self, mock_worker: Mock) -> None:
        history = pd.DataFrame(
            {"Close": [99.0, 101.0]},
            index=pd.to_datetime(["2026-01-01", "2026-01-02"]),
        )
        mock_worker.return_value = ("yfinance_ticker_history_response", history)
        started = time.monotonic()

        price = _latest_market_price(
            "TQQQ",
            timeout_seconds=17,
            expected_session=date(2026, 1, 2),
        )

        self.assertEqual(price, 101.0)
        mock_worker.assert_called_once()
        self.assertEqual(mock_worker.call_args.args, ("TQQQ",))
        self.assertEqual(mock_worker.call_args.kwargs["request_timeout_seconds"], 17.0)
        deadline = mock_worker.call_args.kwargs["deadline"]
        self.assertGreater(deadline, started)
        self.assertLessEqual(deadline - started, 17.1)

    @patch("leveraged_trader.alpaca.run_yfinance_ticker_history_with_deadline")
    def test_latest_market_price_rejects_malformed_worker_error_payloads(self, mock_worker: Mock) -> None:
        malformed_payloads = (
            ("error",),
            ("error", "ValueError"),
            ("error", "ValueError", "message", "extra"),
            ("error", 1, "message"),
            ("error", "ValueError", 1),
            ("error", "", "message"),
            ("error", "ValueError", "x" * 4097),
        )
        for payload in malformed_payloads:
            with self.subTest(payload=payload):
                mock_worker.return_value = payload
                with self.assertRaisesRegex(requests.ConnectionError, "invalid response"):
                    _latest_market_price("TQQQ", timeout_seconds=17)

    @patch("leveraged_trader.alpaca.run_yfinance_ticker_history_with_deadline")
    def test_latest_market_price_maps_valid_worker_errors_consistently(self, mock_worker: Mock) -> None:
        for error_name, exception_type in (
            ("Timeout", requests.Timeout),
            ("ConnectionError", requests.ConnectionError),
            ("ValueError", ValueError),
            ("UnknownWorkerError", requests.RequestException),
        ):
            with self.subTest(error_name=error_name):
                mock_worker.return_value = ("error", error_name, "worker detail")
                with self.assertRaisesRegex(exception_type, "worker detail"):
                    _latest_market_price("TQQQ", timeout_seconds=17)

