    @patch("leveraged_trader.alpaca.requests.delete")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_oversized_sell_cancellation_rejects_parent_change_before_full_cas(
        self,
        mock_get: Mock,
        mock_delete: Mock,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            db_path = Path(tmpdir) / "state.db"
            with (
                closing(sqlite3.connect(db_path)) as conn,
                conn,
                closing(sqlite3.connect(db_path)) as concurrent_conn,
                concurrent_conn,
            ):
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    alpaca_asset_id="asset-tqqq",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="filled",
                    buy_order_qty=3,
                )
                mark_alpaca_managed_buy_filled(
                    conn,
                    1,
                    buy_status="filled",
                    filled_qty=3,
                    filled_avg_price=100,
                    filled_at="2026-01-02T14:31:00Z",
                    target_sell_price=150,
                )
                record_alpaca_managed_sell_order(
                    conn,
                    1,
                    sell_client_order_id="rsi-exit-TQQQ-1-r1",
                    sell_alpaca_order_id="sell-current",
                    sell_submitted_at="2026-01-03T14:32:00Z",
                    sell_status="accepted",
                    sell_order_qty=3,
                    sell_order_limit_price=150,
                    increment_renewal_count=True,
                )
                record_alpaca_managed_sell_generation(conn, 1, "sell-old")
                mock_get.side_effect = [
                    response(
                        200,
                        {
                            "id": "sell-current",
                            "client_order_id": "rsi-exit-TQQQ-1-r1",
                            "asset_id": "asset-tqqq",
                            "status": "stopped",
                            "qty": "3",
                            "limit_price": "150",
                            "filled_qty": "0",
                        },
                    ),
                    response(
                        200,
                        {
                            "id": "sell-old",
                            "client_order_id": "rsi-exit-TQQQ-1",
                            "asset_id": "asset-tqqq",
                            "status": "canceled",
                            "qty": "3",
                            "limit_price": "150",
                            "filled_qty": "1",
                            "filled_avg_price": "150",
                        },
                    ),
                ]
                parent_changes: list[bool] = []

                def change_parent_before_cancellation_cas(
                    *args: object,
                    **kwargs: object,
                ) -> bool:
                    if kwargs.get("sell_status") == "pending_cancel" and not parent_changes:
                        parent_changes.append(
                            mark_alpaca_managed_buy_filled(
                                concurrent_conn,
                                1,
                                buy_status="partially_filled",
                                filled_qty=3,
                                filled_avg_price=100,
                                filled_at=None,
                                target_sell_price=150,
                                buy_alpaca_order_id="buy-1",
                                expected_buy_status="filled",
                                expected_buy_alpaca_order_id="buy-1",
                                expected_filled_qty=3,
                                expected_filled_avg_price=100,
                                expected_target_sell_price=150,
                                expected_sell_client_order_id="rsi-exit-TQQQ-1-r1",
                            )
                        )
                    return update_alpaca_managed_sell_status_if_current(
                        *args,
                        **kwargs,
                    )

                with patch(
                    "leveraged_trader.alpaca.update_alpaca_managed_sell_status_if_current",
                    side_effect=change_parent_before_cancellation_cas,
                ):
                    result = reconcile_alpaca_managed_positions(
                        conn,
                        self.cfg(buy=True, sell=True),
                    )
                managed = load_alpaca_managed_positions(conn).iloc[0]

        self.assertEqual(parent_changes, [True])
        self.assertEqual(result.loc[0, "Status"], "superseded")
        self.assertEqual(managed["buy_status"], "partially_filled")
        self.assertEqual(managed["sold_qty"], 1)
        self.assertEqual(managed["remaining_qty"], 2)
        mock_delete.assert_not_called()

