    @patch("leveraged_trader.alpaca.requests.delete")
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_terminal_zero_fill_closed_buy_is_reaudited_reopened_and_protected(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
    ) -> None:
        for terminal_status in ("canceled", "done_for_day"):
            with self.subTest(terminal_status=terminal_status), closing(sqlite3.connect(":memory:")) as conn, conn:
                mock_get.reset_mock()
                mock_post.reset_mock()
                mock_delete.reset_mock()
                init_state_db(conn)
                position_id = save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    alpaca_asset_id="asset-tqqq",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-late-fill",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status=terminal_status,
                    buy_order_qty=2,
                    buy_order_limit_price=105,
                )
                conn.execute(
                    "UPDATE alpaca_managed_positions SET closed_at = CURRENT_TIMESTAMP WHERE id = ?",
                    (position_id,),
                )
                conn.commit()
                self.assertIsNone(
                    conn.execute(
                        "SELECT filled_qty FROM alpaca_managed_positions WHERE id = ?",
                        (position_id,),
                    ).fetchone()[0]
                )
                buy_observation = {
                    "id": "buy-late-fill",
                    "client_order_id": "rsi-buy-TQQQ-20260102",
                    "asset_id": "asset-tqqq",
                    "status": terminal_status,
                    "qty": "2",
                    "limit_price": "105",
                    "filled_qty": "1",
                    "filled_avg_price": "100",
                    "filled_at": "2026-01-02T14:31:00Z",
                }
                mock_get.side_effect = [
                    response(200, buy_observation),
                    *([response(200, buy_observation)] if terminal_status == "done_for_day" else []),
                    response(200, []),
                    response(
                        200,
                        [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "1"}],
                    ),
                    *final_managed_sell_pre_submit_responses(qty=1),
                ]
                mock_post.return_value = response(
                    200,
                    {
                        "id": "sell-late-fill",
                        "client_order_id": "rsi-exit-TQQQ-1",
                        "asset_id": "asset-tqqq",
                        "status": "accepted",
                        "qty": "1",
                        "limit_price": "150",
                        "filled_qty": "0",
                    },
                )
                mock_delete.return_value = response(204, {}, complete_orders=False)

                if terminal_status == "done_for_day":
                    with self.assertRaises(AlpacaReconciliationError) as raised:
                        reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
                    result = raised.exception.results
                else:
                    result = reconcile_alpaca_managed_positions(
                        conn,
                        self.cfg(buy=True, sell=True),
                    )
                managed = load_alpaca_managed_positions(conn).iloc[0]

                self.assertEqual(
                    result["Status"].tolist(),
                    ["pending_cancel", "pending_cancel", "accepted"]
                    if terminal_status == "done_for_day"
                    else ["reopened", "accepted"],
                )
                self.assertEqual(
                    managed["buy_status"],
                    "pending_cancel" if terminal_status == "done_for_day" else terminal_status,
                )
                self.assertEqual(managed["filled_qty"], 1)
                self.assertEqual(managed["filled_avg_price"], 100)
                self.assertEqual(managed["target_sell_price"], 150)
                self.assertEqual(managed["remaining_qty"], 1)
                self.assertTrue(pd.isna(managed["closed_at"]))
                self.assertEqual(managed["sell_client_order_id"], "rsi-exit-TQQQ-1")
                self.assertEqual(managed["sell_alpaca_order_id"], "sell-late-fill")
                self.assertEqual(managed["sell_status"], "accepted")
                self.assertTrue(mock_get.call_args_list[0].args[0].endswith("/v2/orders/buy-late-fill"))
                self.assertEqual(
                    mock_delete.call_count,
                    2 if terminal_status == "done_for_day" else 0,
                )
                mock_post.assert_called_once()

