    def test_reopened_closed_sell_shortfall_is_protected_in_same_pass(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        for observed_sell_status in ("filled", "canceled", "partially_filled"):
            with (
                self.subTest(observed_sell_status=observed_sell_status),
                closing(sqlite3.connect(":memory:")) as conn,
                conn,
            ):
                mock_get.reset_mock()
                mock_post.reset_mock()
                mock_post.side_effect = None
                init_state_db(conn)
                save_alpaca_managed_buy_order(
                    conn,
                    symbol="TQQQ",
                    alpaca_asset_id="asset-tqqq",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="filled",
                )
                mark_alpaca_managed_buy_filled(
                    conn,
                    1,
                    buy_status="filled",
                    filled_qty=2,
                    filled_avg_price=100,
                    filled_at="2026-01-02T14:31:00Z",
                    target_sell_price=150,
                )
                record_alpaca_managed_sell_order(
                    conn,
                    1,
                    sell_client_order_id="rsi-exit-TQQQ-1",
                    sell_alpaca_order_id="sell-1",
                    sell_submitted_at="2026-01-02T14:32:00Z",
                    sell_status="filled",
                    sell_order_qty=2,
                    sell_order_limit_price=150,
                )
                mark_alpaca_managed_sell_filled(
                    conn,
                    1,
                    sell_status="filled",
                    sell_filled_qty=2,
                    sell_filled_avg_price=150,
                    sell_filled_at="2026-01-02T14:33:00Z",
                    sell_broker_updated_at="2026-01-02T14:31:00Z",
                    sell_alpaca_order_id="sell-1",
                )
                conn.execute("UPDATE alpaca_managed_positions SET closed_at = CURRENT_TIMESTAMP")
                conn.commit()
                corrected_sell = {
                    "id": "sell-1",
                    "client_order_id": "rsi-exit-TQQQ-1",
                    "asset_id": "asset-tqqq",
                    "status": observed_sell_status,
                    "qty": "2",
                    "limit_price": "150",
                    "filled_qty": "1",
                    "filled_avg_price": "150",
                    "expires_at": "2099-01-01T00:00:00Z",
                }
                broker_responses = [
                    response(
                        200,
                        {
                            "id": "buy-1",
                            "client_order_id": "rsi-buy-TQQQ-20260102",
                            "asset_id": "asset-tqqq",
                            "status": "filled",
                            "qty": "2",
                            "limit_price": "105",
                            "filled_qty": "2",
                            "filled_avg_price": "100",
                        },
                    ),
                    response(200, corrected_sell),
                    response(200, corrected_sell),
                ]
                if observed_sell_status in {"filled", "canceled"}:
                    broker_responses.extend(
                        [
                            response(200, [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "1"}]),
                            response(404, {}),
                            response(200, corrected_sell),
                            response(200, []),
                            response(
                                200,
                                [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "1"}],
                            ),
                        ]
                    )
                mock_get.side_effect = broker_responses
                mock_post.return_value = response(
                    200,
                    {
                        "id": "sell-2",
                        "client_order_id": "rsi-exit-TQQQ-1-r1",
                        "asset_id": "asset-tqqq",
                        "status": "accepted",
                        "qty": "1",
                        "limit_price": "150",
                        "filled_qty": "0",
                    },
                )

                result = reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
                managed = load_alpaca_managed_positions(conn)

                self.assertEqual(
                    result["Status"].tolist(),
                    ["reopened", "partially_filled"]
                    if observed_sell_status == "partially_filled"
                    else ["reopened", "renewed"],
                )
                self.assertTrue(pd.isna(managed.loc[0, "closed_at"]))
                if observed_sell_status == "partially_filled":
                    self.assertEqual(managed.loc[0, "sell_client_order_id"], "rsi-exit-TQQQ-1")
                    self.assertEqual(managed.loc[0, "sell_alpaca_order_id"], "sell-1")
                    self.assertEqual(managed.loc[0, "sell_renewal_count"], 0)
                    mock_post.assert_not_called()
                else:
                    self.assertEqual(managed.loc[0, "sell_client_order_id"], "rsi-exit-TQQQ-1-r1")
                    self.assertEqual(managed.loc[0, "sell_alpaca_order_id"], "sell-2")
                    self.assertEqual(managed.loc[0, "sell_renewal_count"], 1)
                    mock_post.assert_called_once()

