    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_initial_fractional_sell_rejects_a_concurrent_whole_share_parent(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        buy_order = {
            "id": "buy-1",
            "client_order_id": "rsi-buy-TQQQ-20260102",
            "asset_id": "asset-tqqq",
            "symbol": "TQQQ",
            "side": "buy",
            "type": "limit",
            "time_in_force": "day",
            "extended_hours": False,
            "status": "partially_filled",
            "qty": "2",
            "filled_qty": "0.5",
            "filled_avg_price": "100",
            "limit_price": "105",
            "submitted_at": "2026-01-02T14:30:00Z",
            "updated_at": "2026-01-02T14:31:00Z",
            "filled_at": "2026-01-02T14:31:00Z",
        }
        concurrent_states: list[tuple] = []

        with tempfile.TemporaryDirectory() as tmpdir:
            db_path = Path(tmpdir) / "state.db"
            with closing(sqlite3.connect(db_path)) as setup_conn, setup_conn:
                init_state_db(setup_conn)
                save_alpaca_managed_buy_order(
                    setup_conn,
                    symbol="TQQQ",
                    alpaca_asset_id="asset-tqqq",
                    signal_symbol="QQQ",
                    buy_rsi=30,
                    profit_target_multiple=1.5,
                    buy_signal_date="2026-01-02",
                    buy_client_order_id="rsi-buy-TQQQ-20260102",
                    buy_alpaca_order_id="buy-1",
                    buy_submitted_at="2026-01-02T14:30:00Z",
                    buy_status="partially_filled",
                    buy_order_qty=2,
                    buy_order_limit_price=105,
                )
                mark_alpaca_managed_buy_filled(
                    setup_conn,
                    1,
                    buy_status="partially_filled",
                    filled_qty=0.5,
                    filled_avg_price=100,
                    filled_at="2026-01-02T14:31:00Z",
                    target_sell_price=150,
                    buy_fill_broker_updated_at="2026-01-02T14:31:00Z",
                    buy_fill_component_revisions={"buy-1": "2026-01-02T14:31:00Z"},
                )

            with (
                closing(sqlite3.connect(db_path)) as conn,
                conn,
                closing(sqlite3.connect(db_path)) as concurrent_conn,
                concurrent_conn,
            ):

                def broker_get(url: str, **kwargs: object) -> Mock:
                    if url.endswith("/v2/orders/buy-1"):
                        return response(200, buy_order)
                    if url.endswith("/v2/orders") and kwargs.get("params") is not None:
                        self.assertTrue(
                            mark_alpaca_managed_buy_filled(
                                concurrent_conn,
                                1,
                                buy_status="partially_filled",
                                filled_qty=1,
                                filled_avg_price=100,
                                filled_at=None,
                                target_sell_price=150,
                                buy_alpaca_order_id="buy-1",
                                expected_buy_status="partially_filled",
                                expected_buy_alpaca_order_id="buy-1",
                                expected_filled_qty=0.5,
                                expected_filled_avg_price=100,
                                expected_target_sell_price=150,
                                expected_sell_client_order_id=None,
                            )
                        )
                        concurrent_states.append(
                            concurrent_conn.execute(
                                "SELECT state_revision, filled_qty, remaining_qty, sell_status, "
                                "sell_client_order_id FROM alpaca_managed_positions WHERE id = 1"
                            ).fetchone()
                        )
                        return response(200, [], complete_orders=False)
                    raise AssertionError(f"unexpected Alpaca GET: {url}")

                mock_get.side_effect = broker_get
                result = reconcile_alpaca_managed_positions(
                    conn,
                    self.cfg(buy=True, sell=True),
                )
                final_state = conn.execute(
                    "SELECT state_revision, filled_qty, remaining_qty, sell_status, "
                    "sell_client_order_id FROM alpaca_managed_positions WHERE id = 1"
                ).fetchone()

        self.assertEqual(result["Action"].tolist(), ["buy", "sell"])
        self.assertEqual(result["Status"].tolist(), ["partially_filled", "superseded"])
        self.assertEqual(result["Qty"].tolist(), [0.5, 0.5])
        self.assertEqual(len(concurrent_states), 1)
        self.assertEqual(concurrent_states[0][1:], (1, 1, None, None))
        self.assertEqual(final_state, concurrent_states[0])
        self.assertEqual(mock_get.call_count, 2)
        mock_post.assert_not_called()

