    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_missing_sell_retry_open_sell_diagnostic_rejects_newer_parent_state(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            db_path = Path(tmp) / "state.sqlite"
            with closing(sqlite3.connect(db_path)) as setup_conn, setup_conn:
                init_state_db(setup_conn)
                self.seed_missing_managed_sell_retry(setup_conn)

            with (
                closing(sqlite3.connect(db_path)) as observer_conn,
                observer_conn,
                closing(sqlite3.connect(db_path)) as correction_conn,
                correction_conn,
            ):
                manual_sell = {
                    "id": "manual-sell",
                    "client_order_id": "manual-sell",
                    "asset_id": "asset-tqqq",
                    "symbol": "TQQQ",
                    "side": "sell",
                    "type": "limit",
                    "time_in_force": "gtc",
                    "extended_hours": False,
                    "status": "accepted",
                    "qty": "2",
                    "filled_qty": "0",
                    "limit_price": "150",
                }
                claimed_tokens: list[str] = []

                def broker_get(url: str, **kwargs: object) -> Mock:
                    if url.endswith("/v2/orders:by_client_order_id"):
                        return error_response(404, {})
                    if url.endswith("/v2/positions"):
                        return response(
                            200,
                            [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "2"}],
                        )
                    if url.endswith("/v2/orders") and kwargs.get("params") is not None:
                        claimed_status, claimed_token = correction_conn.execute(
                            "SELECT sell_status, sell_submission_retry_claimed_at "
                            "FROM alpaca_managed_positions WHERE id = 1"
                        ).fetchone()
                        self.assertEqual(claimed_status, "submission_retrying")
                        self.assertIsNotNone(claimed_token)
                        claimed_tokens.append(str(claimed_token))
                        self.assertTrue(
                            mark_alpaca_managed_buy_filled(
                                correction_conn,
                                1,
                                buy_status="partially_filled",
                                filled_qty=2,
                                filled_avg_price=100,
                                filled_at=None,
                                target_sell_price=150,
                                buy_alpaca_order_id="buy-1",
                                expected_buy_status="filled",
                                expected_buy_alpaca_order_id="buy-1",
                                expected_filled_qty=2,
                                expected_filled_avg_price=100,
                                expected_target_sell_price=150,
                                expected_sell_client_order_id="rsi-exit-TQQQ-1",
                            )
                        )
                        return response(200, [manual_sell], complete_orders=False)
                    raise AssertionError(f"unexpected Alpaca GET: {url}")

                mock_get.side_effect = broker_get
                with self.assertRaises(AlpacaReconciliationError) as raised:
                    reconcile_alpaca_managed_positions(
                        observer_conn,
                        self.cfg(buy=True, sell=True),
                    )
                managed = load_alpaca_managed_positions(observer_conn).iloc[0]

        self.assertEqual(claimed_tokens, [managed["sell_submission_retry_claimed_at"]])
        self.assertEqual(raised.exception.results.loc[0, "Status"], "superseded")
        self.assertEqual(managed["buy_status"], "partially_filled")
        self.assertEqual(managed["sell_status"], "submission_retrying")
        self.assertTrue(pd.isna(managed["sell_alpaca_order_id"]))
        self.assertTrue(pd.isna(managed["closed_at"]))
        mock_post.assert_not_called()

