    @patch("leveraged_trader.alpaca.requests.delete")
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_missing_sell_retry_cancels_wrong_intent_history_without_accounting_then_retries(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
    ) -> None:
        active_wrong_intent_sell = {
            "id": "sell-old",
            "client_order_id": "rsi-exit-TQQQ-1",
            "asset_id": "asset-tqqq",
            "symbol": "TQQQ",
            "side": "sell",
            "position_intent": "sell_to_open",
            "type": "limit",
            "time_in_force": "gtc",
            "extended_hours": False,
            "status": "partially_filled",
            "qty": "2",
            "filled_qty": "1",
            "filled_avg_price": "160",
            "limit_price": "150",
        }
        canceled_wrong_intent_sell = {
            **active_wrong_intent_sell,
            "status": "canceled",
        }
        submitted_protection = {
            "id": "sell-new",
            "client_order_id": "rsi-exit-TQQQ-1-r1",
            "asset_id": "asset-tqqq",
            "symbol": "TQQQ",
            "side": "sell",
            "position_intent": "sell_to_close",
            "type": "limit",
            "time_in_force": "gtc",
            "extended_hours": False,
            "status": "accepted",
            "qty": "2",
            "filled_qty": "0",
            "limit_price": "150",
            "submitted_at": "2026-01-05T14:30:00Z",
            "updated_at": "2026-01-05T14:30:00Z",
            "expires_at": "2027-06-30T20:00:00Z",
        }

        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_filled_managed_buy(conn)
            record_alpaca_managed_sell_order(
                conn,
                1,
                sell_client_order_id="rsi-exit-TQQQ-1",
                sell_alpaca_order_id="sell-old",
                sell_submitted_at="2026-01-02T14:32:00Z",
                sell_status="expired",
                sell_order_qty=2,
                sell_order_limit_price=150,
            )
            self.assertEqual(
                claim_alpaca_managed_sell_replacement(
                    conn,
                    1,
                    prior_sell_client_order_id="rsi-exit-TQQQ-1",
                    prior_sell_alpaca_order_id="sell-old",
                    prior_renewal_count=0,
                    replacement_sell_client_order_id="rsi-exit-TQQQ-1-r1",
                    requested_remaining_qty=2,
                    expected_target_sell_price=150,
                    notes="replacement claimed",
                ),
                2,
            )
            mock_get.side_effect = [
                error_response(404, {}),
                response(200, active_wrong_intent_sell, complete_orders=False),
            ]
            deletion_snapshots: list[tuple[str, float, float]] = []

            def cancel_wrong_intent_after_fence(*_args: object, **_kwargs: object) -> Mock:
                deletion_snapshots.append(
                    conn.execute(
                        "SELECT sell_status, sold_qty, remaining_qty FROM alpaca_managed_positions WHERE id = 1"
                    ).fetchone()
                )
                return response(204, {}, complete_orders=False)

            mock_delete.side_effect = cancel_wrong_intent_after_fence
            with self.assertRaises(AlpacaReconciliationError) as first_failure:
                reconcile_alpaca_managed_positions(
                    conn,
                    self.cfg(buy=True, sell=True),
                )
            after_cancellation_request = load_alpaca_managed_positions(conn).iloc[0]

            def retry_get(url: str, **_kwargs: object) -> Mock:
                if url.endswith("/v2/orders:by_client_order_id"):
                    return error_response(404, {})
                if url.endswith("/v2/orders/sell-old"):
                    return response(
                        200,
                        canceled_wrong_intent_sell,
                        complete_orders=False,
                    )
                if url.endswith("/v2/positions"):
                    return response(
                        200,
                        [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "2"}],
                        complete_orders=False,
                    )
                if url.endswith("/v2/orders"):
                    return response(200, [], complete_orders=False)
                raise AssertionError(f"unexpected Alpaca GET: {url}")

            mock_get.side_effect = retry_get
            mock_post.return_value = response(
                200,
                submitted_protection,
                complete_orders=False,
            )
            retry_result = reconcile_alpaca_managed_positions(
                conn,
                self.cfg(buy=True, sell=True),
            )
            after_retry = load_alpaca_managed_positions(conn).iloc[0]
            wrong_intent_ledger = conn.execute(
                "SELECT filled_qty, filled_value FROM alpaca_managed_sell_fills "
                "WHERE managed_position_id = 1 AND alpaca_order_id = 'sell-old'"
            ).fetchone()

        self.assertEqual(first_failure.exception.results.loc[0, "Status"], "pending_cancel")
        self.assertIn("incompatible position intent", first_failure.exception.results.loc[0, "Message"])
        self.assertEqual(deletion_snapshots, [("pending_cancel", 0.0, 2.0)])
        self.assertEqual(after_cancellation_request["sell_status"], "pending_cancel")
        self.assertEqual(after_cancellation_request["sold_qty"], 0)
        self.assertEqual(after_cancellation_request["sold_value"], 0)
        self.assertEqual(after_cancellation_request["remaining_qty"], 2)
        self.assertEqual(retry_result.loc[0, "Status"], "renewed")
        self.assertEqual(after_retry["sell_status"], "accepted")
        self.assertEqual(after_retry["sell_alpaca_order_id"], "sell-new")
        self.assertEqual(after_retry["sold_qty"], 0)
        self.assertEqual(after_retry["remaining_qty"], 2)
        self.assertEqual(wrong_intent_ledger, (0.0, 0.0))
        mock_delete.assert_called_once()
        mock_post.assert_called_once()

