    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_missing_sell_retry_rechecks_position_after_open_orders_before_post(
        self,
        mock_get: Mock,
        mock_post: Mock,
    ) -> None:
        live_qty = 2
        position_snapshots = 0
        open_order_snapshots = 0

        def broker_get(url: str, **_kwargs: object) -> Mock:
            nonlocal live_qty, position_snapshots, open_order_snapshots
            if url.endswith("/v2/orders:by_client_order_id"):
                return error_response(404, {})
            if url.endswith("/v2/positions"):
                position_snapshots += 1
                positions = [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": str(live_qty)}] if live_qty else []
                return response(200, positions, complete_orders=False)
            if url.endswith("/v2/orders"):
                open_order_snapshots += 1
                if open_order_snapshots == 1:
                    live_qty = 0
                return response(200, [], complete_orders=False)
            raise AssertionError(f"unexpected Alpaca GET: {url}")

        mock_get.side_effect = broker_get
        with closing(sqlite3.connect(":memory:")) as conn, conn:
            init_state_db(conn)
            self.seed_missing_managed_sell_retry(conn)

            with self.assertRaises(AlpacaReconciliationError) as raised:
                reconcile_alpaca_managed_positions(conn, self.cfg(buy=True, sell=True))
            persisted = conn.execute(
                "SELECT sell_status, sell_submission_retry_claimed_at FROM alpaca_managed_positions WHERE id = 1"
            ).fetchone()

        self.assertEqual(raised.exception.results.loc[0, "Status"], "position_quantity_mismatch")
        self.assertEqual(persisted, ("submission_not_found", None))
        self.assertEqual(position_snapshots, 2)
        self.assertEqual(open_order_snapshots, 2)
        mock_post.assert_not_called()

