    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_missing_sell_retry_quarantines_ambiguous_order_not_yet_visible(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            db_path = Path(tmp) / "state.sqlite"
            with closing(sqlite3.connect(db_path)) as setup_conn, setup_conn:
                init_state_db(setup_conn)
                self.seed_missing_managed_sell_retry(setup_conn)

            with (
                closing(sqlite3.connect(db_path)) as observer_conn,
                observer_conn,
                closing(sqlite3.connect(db_path)) as correction_conn,
                correction_conn,
            ):
                mock_get.side_effect = [
                    error_response(404, {}),
                    response(
                        200,
                        [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "2"}],
                        complete_orders=False,
                    ),
                    response(200, [], complete_orders=False),
                    *final_managed_sell_pre_submit_responses(),
                    error_response(404, {}),
                ]

                def timeout_after_correction(*_args: object, **_kwargs: object) -> Mock:
                    self.apply_concurrent_old_sell_fill(correction_conn)
                    raise requests.exceptions.Timeout("accepted but not visible")

                mock_post.side_effect = timeout_after_correction
                with self.assertRaises(AlpacaReconciliationError) as raised:
                    reconcile_alpaca_managed_positions(observer_conn, self.cfg(buy=True, sell=True))
                row = observer_conn.execute(
                    "SELECT sell_status, sell_alpaca_order_id, sold_qty, remaining_qty, "
                    "sell_submission_retry_claimed_at "
                    "FROM alpaca_managed_positions WHERE id = 1"
                ).fetchone()

                mock_get.reset_mock()
                mock_get.side_effect = [
                    response(
                        200,
                        {
                            "id": "sell-retry",
                            "client_order_id": "rsi-exit-TQQQ-1",
                            "status": "accepted",
                            "qty": "2",
                            "filled_qty": "0",
                            "limit_price": "150",
                            "submitted_at": "2026-01-02T14:34:00Z",
                            "expires_at": "2027-01-02T20:00:00Z",
                        },
                    )
                ]
                mock_delete.return_value = response(204, {}, complete_orders=False)
                with self.assertRaises(AlpacaReconciliationError) as visible:
                    reconcile_alpaca_managed_positions(observer_conn, self.cfg(buy=True, sell=True))
                visible_ledger = observer_conn.execute(
                    "SELECT alpaca_order_id, filled_qty FROM alpaca_managed_sell_fills ORDER BY alpaca_order_id"
                ).fetchall()

                mock_get.reset_mock()
                mock_get.side_effect = [
                    response(
                        200,
                        {
                            "id": "sell-retry",
                            "client_order_id": "rsi-exit-TQQQ-1",
                            "status": "canceled",
                            "qty": "2",
                            "filled_qty": "0",
                            "limit_price": "150",
                            "submitted_at": "2026-01-02T14:34:00Z",
                        },
                    )
                ]
                with self.assertRaises(AlpacaReconciliationError) as terminal:
                    reconcile_alpaca_managed_positions(observer_conn, self.cfg(buy=True, sell=True))
                resolved_row = observer_conn.execute(
                    "SELECT sell_status, sell_client_order_id, sell_alpaca_order_id, "
                    "sell_submission_retry_claimed_at FROM alpaca_managed_positions WHERE id = 1"
                ).fetchone()

        self.assertEqual(raised.exception.results.loc[0, "Status"], "superseded")
        self.assertIn("possible stale broker exposure is quarantined", raised.exception.results.loc[0, "Message"])
        self.assertEqual(row[:4], ("quantity_mismatch", "sell-old", 1, 1))
        self.assertIsNotNone(row[4])
        self.assertEqual(visible.exception.results.loc[0, "Status"], "pending_cancel")
        self.assertEqual(visible_ledger, [("sell-old", 1.0), ("sell-retry", 0.0)])
        self.assertIn("quarantine was released", terminal.exception.results.loc[0, "Message"])
        self.assertEqual(resolved_row, ("submission_unknown", "rsi-exit-TQQQ-1", "sell-old", None))
        mock_delete.assert_called_once()

