    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_retained_retry_balanced_canceled_lineage_releases_sticky_quarantine(
        self,
        mock_get: Mock,
        mock_post: Mock,
        mock_delete: Mock,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            db_path = Path(tmp) / "state.sqlite"
            with closing(sqlite3.connect(db_path)) as setup_conn, setup_conn:
                init_state_db(setup_conn)
                self.seed_missing_managed_sell_retry(setup_conn)

            with (
                closing(sqlite3.connect(db_path)) as observer_conn,
                observer_conn,
                closing(sqlite3.connect(db_path)) as correction_conn,
                correction_conn,
            ):
                mock_get.side_effect = [
                    error_response(404, {}),
                    response(
                        200,
                        [{"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "2"}],
                        complete_orders=False,
                    ),
                    response(200, [], complete_orders=False),
                    *final_managed_sell_pre_submit_responses(),
                    error_response(404, {}),
                ]

                def timeout_after_revision_change(*_args: object, **_kwargs: object) -> Mock:
                    correction_conn.execute(
                        "UPDATE alpaca_managed_positions SET notes = 'concurrent correction' WHERE id = 1"
                    )
                    correction_conn.commit()
                    raise requests.exceptions.Timeout("accepted but not visible")

                mock_post.side_effect = timeout_after_revision_change
                with self.assertRaises(AlpacaReconciliationError):
                    reconcile_alpaca_managed_positions(observer_conn, self.cfg(buy=True, sell=True))

                partially_filled = {
                    "id": "sell-retry",
                    "client_order_id": "rsi-exit-TQQQ-1",
                    "status": "partially_filled",
                    "qty": "2",
                    "filled_qty": "2",
                    "filled_avg_price": "155",
                    "limit_price": "150",
                    "submitted_at": "2026-01-02T14:34:00Z",
                    "expires_at": "2027-01-02T20:00:00Z",
                }
                mock_get.side_effect = [response(200, partially_filled)]
                mock_delete.return_value = response(204, {}, complete_orders=False)
                with self.assertRaises(AlpacaReconciliationError):
                    reconcile_alpaca_managed_positions(observer_conn, self.cfg(buy=True, sell=True))

                mock_get.side_effect = [response(200, {**partially_filled, "status": "canceled"})]
                with self.assertRaises(AlpacaReconciliationError) as terminal:
                    reconcile_alpaca_managed_positions(observer_conn, self.cfg(buy=True, sell=True))
                resolved = observer_conn.execute(
                    "SELECT sell_status, sell_client_order_id, sell_alpaca_order_id, sold_qty, remaining_qty, "
                    "sell_submission_retry_claimed_at FROM alpaca_managed_positions WHERE id = 1"
                ).fetchone()

        self.assertIn("quarantine was released", terminal.exception.results.loc[0, "Message"])
        self.assertEqual(resolved, ("submission_unknown", "rsi-exit-TQQQ-1", None, 2, 0, None))
        mock_delete.assert_called_once()

