    @patch("leveraged_trader.alpaca._latest_market_price", return_value=100.0)
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_public_buy_final_snapshot_blocks_a_new_holding_without_managed_state(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        clock_calls = 0
        position_is_visible = False

        def get_response(url: str, **_kwargs: object) -> Mock:
            nonlocal clock_calls, position_is_visible
            if "/v2/orders:by_client_order_id" in url:
                return response(404, {})
            if url.endswith("/v2/orders"):
                return response(200, [])
            if "/v2/assets/" in url:
                return asset_response("TQQQ", status="active", tradable=True)
            if "/v2/positions/" in url:
                return (
                    response(200, {"asset_id": "asset-tqqq", "symbol": "TQQQ", "qty": "1"})
                    if position_is_visible
                    else response(404, {})
                )
            if url.endswith("/v2/clock"):
                clock_calls += 1
                if clock_calls == 2:
                    position_is_visible = True
                return response(
                    200,
                    {
                        "is_open": False,
                        "timestamp": "2026-01-05T13:30:00Z",
                        "next_open": "2026-01-05T14:30:00Z",
                    },
                )
            if url.endswith("/v2/calendar"):
                return response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}])
            if url.endswith("/v2/account"):
                return response(200, {"cash": "3000"})
            raise AssertionError(f"unexpected Alpaca GET: {url}")

        mock_get.side_effect = get_response

        result = submit_alpaca_paper_buy_orders(
            pd.DataFrame([{"Asset": "TQQQ", "Date": "2026-01-02"}]),
            self.cfg(buy=True),
        )

        self.assertEqual(result.loc[0, "Status"], "held")
        self.assertEqual(clock_calls, 2)
        mock_post.assert_not_called()

