    @patch("leveraged_trader.alpaca._latest_market_price", return_value=100.0)
    @patch("leveraged_trader.alpaca.requests.post")
    @patch("leveraged_trader.alpaca.requests.get")
    def test_unmanaged_malformed_successful_buy_is_fatal_and_aborts_later_orders(
        self,
        mock_get: Mock,
        mock_post: Mock,
        _mock_latest_price: Mock,
    ) -> None:
        def broker_get(url: str, **_kwargs: object) -> Mock:
            if "/v2/orders:by_client_order_id" in url or "/v2/positions/" in url:
                return response(404, {})
            if url.endswith("/v2/orders"):
                return response(200, [])
            if "/v2/assets/" in url:
                return asset_response(url.rsplit("/", 1)[-1], status="active", tradable=True)
            if url.endswith("/v2/clock"):
                return response(
                    200,
                    {
                        "is_open": False,
                        "timestamp": "2026-01-05T13:30:00Z",
                        "next_open": "2026-01-05T14:30:00Z",
                    },
                )
            if url.endswith("/v2/calendar"):
                return response(200, [{"date": "2026-01-02"}, {"date": "2026-01-05"}])
            if url.endswith("/v2/account"):
                return response(200, {"cash": "6000"})
            raise AssertionError(f"unexpected Alpaca GET: {url}")

        mock_get.side_effect = broker_get
        mock_post.return_value = response(200, [], complete_orders=False)

        with self.assertRaises(AlpacaBuyBatchError) as raised:
            submit_alpaca_paper_buy_orders(
                pd.DataFrame(
                    [
                        {"Asset": "TQQQ", "Date": "2026-01-02"},
                        {"Asset": "SQQQ", "Date": "2026-01-02"},
                    ]
                ),
                self.cfg(buy=True),
            )

        self.assertEqual(
            raised.exception.results["Status"].tolist(),
            ["identity_mismatch", "batch_aborted"],
        )
        self.assertTrue(raised.exception.broker_side_effects_possible)
        self.assertEqual(mock_post.call_count, 1)

