    def test_public_buy_rejects_active_caller_transaction_before_broker_work(self) -> None:
        with closing(sqlite3.connect(":memory:")) as conn:
            init_state_db(conn)
            conn.execute("CREATE TABLE caller_probe (value INTEGER NOT NULL)")
            conn.commit()
            conn.execute("BEGIN")
            conn.execute("INSERT INTO caller_probe (value) VALUES (7)")
            cfg = AlpacaOrderConfig(
                enabled=True,
                api_key_id=" key ",
                api_secret_key=" secret ",
                buy_limit_buffer_bps=Fraction(1, 10),
            )

            with (
                patch("leveraged_trader.alpaca.AlpacaClient") as mock_client,
                patch("leveraged_trader.alpaca._submit_alpaca_paper_buy_orders_impl") as mock_submit_impl,
                patch("leveraged_trader.alpaca.requests.post") as mock_post,
                self.assertRaisesRegex(ValueError, "no active transaction"),
            ):
                _submit_alpaca_paper_buy_orders(
                    pd.DataFrame(
                        [
                            {
                                "Asset": "TQQQ",
                                "Date": "2026-01-02",
                                "RSI Observation Date": "2026-01-02",
                                "RSI Symbol": "QQQ",
                                "Buy RSI": 30.0,
                                "Sell Return Multiple": 1.5,
                            }
                        ]
                    ),
                    cfg,
                    conn=conn,
                )

            self.assertTrue(conn.in_transaction)
            self.assertEqual(conn.execute("SELECT value FROM caller_probe").fetchall(), [(7,)])
            self.assertEqual(cfg.api_key_id, " key ")
            self.assertEqual(cfg.api_secret_key, " secret ")
            self.assertEqual(cfg.buy_limit_buffer_bps, Fraction(1, 10))
            self.assertIs(type(cfg.buy_limit_buffer_bps), Fraction)
            mock_client.assert_not_called()
            mock_submit_impl.assert_not_called()
            mock_post.assert_not_called()
            conn.rollback()
            self.assertEqual(conn.execute("SELECT value FROM caller_probe").fetchall(), [])

