    def test_exception_diagnostics_never_call_exception_str(self) -> None:
        class HostileError(ValueError):
            str_calls = 0

            def __str__(self) -> str:
                type(self).str_calls += 1
                raise AssertionError("exception __str__ must not be called")

        class HostileHTTPError(HTTPError):
            str_calls = 0

            def __str__(self) -> str:
                type(self).str_calls += 1
                raise AssertionError("HTTP exception __str__ must not be called")

        ordinary_error = HostileError("ordinary safe detail")
        self.assertEqual(
            _alpaca_exception_diagnostic(ordinary_error, cfg=self.cfg()),
            "ordinary safe detail",
        )

        for broker_response in (
            None,
            raw_response(403, '{"message":"authentication failed"}'),
        ):
            with self.subTest(has_response=broker_response is not None):
                http_error = HostileHTTPError("403 Client Error")
                http_error.response = broker_response
                diagnostic = _alpaca_exception_diagnostic(http_error, cfg=self.cfg())

                self.assertIn("403 Client Error", diagnostic)

        self.assertEqual(HostileError.str_calls, 0)
        self.assertEqual(HostileHTTPError.str_calls, 0)

    def test_public_alpaca_boundaries_do_not_render_string_subclass_credentials(self) -> None:
        class HostileCredential(str):
            hook_calls: list[str] = []

            def _reject_hook(self, hook: str) -> None:
                type(self).hook_calls.append(hook)
                raise RuntimeError(f"{hook} exposed {str.__str__(self)}")

            def __str__(self) -> str:
                self._reject_hook("__str__")

            def __repr__(self) -> str:
                self._reject_hook("__repr__")

            def strip(self, _characters: str | None = None) -> str:
                self._reject_hook("strip")

            def __len__(self) -> int:
                self._reject_hook("__len__")

            def __getitem__(self, _key: object) -> str:
                self._reject_hook("__getitem__")

            def __iter__(self):
                self._reject_hook("__iter__")

        def hostile_cfg() -> AlpacaOrderConfig:
            return AlpacaOrderConfig(
                api_key_id=HostileCredential("boundary-key-7zQ42"),
                api_secret_key=HostileCredential("boundary-secret-7zQ42"),
            )

        with closing(sqlite3.connect(":memory:")) as conn:
            operations = (
                ("buy", lambda cfg: _submit_alpaca_paper_buy_orders(pd.DataFrame(), cfg)),
                ("reconciliation", lambda cfg: reconcile_alpaca_managed_positions(conn, cfg)),
                ("migration", lambda cfg: migrate_alpaca_managed_position_symbols(conn, cfg)),
                ("sell", lambda cfg: submit_alpaca_paper_sell_orders(pd.DataFrame(), cfg)),
            )
            for label, operation in operations:
                with self.subTest(boundary=label):
                    operation(hostile_cfg())

        self.assertEqual(HostileCredential.hook_calls, [])

    def test_public_alpaca_boundaries_sanitize_base_exception_with_hostile_credentials(self) -> None:
        class HostileCredential(str):
            str_calls = 0

            def __str__(self) -> str:
                type(self).str_calls += 1
                raise RuntimeError(f"credential renderer exposed {str.__str__(self)}")

        with closing(sqlite3.connect(":memory:")) as conn:
            boundaries = (
                (
                    "buy",
                    "leveraged_trader.alpaca._submit_alpaca_paper_buy_orders_public_impl",
                    lambda cfg: _submit_alpaca_paper_buy_orders(pd.DataFrame(), cfg),
                ),
                (
                    "reconciliation",
                    "leveraged_trader.alpaca._reconcile_alpaca_managed_positions_impl",
                    lambda cfg: reconcile_alpaca_managed_positions(conn, cfg),
                ),
                (
                    "migration",
                    "leveraged_trader.alpaca._migrate_alpaca_managed_position_symbols_impl",
                    lambda cfg: migrate_alpaca_managed_position_symbols(conn, cfg),
                ),
                (
                    "sell",
                    "leveraged_trader.alpaca._submit_alpaca_paper_sell_orders_impl",
                    lambda cfg: submit_alpaca_paper_sell_orders(pd.DataFrame(), cfg),
                ),
            )
            for label, target, operation in boundaries:
                key = f"boundary-{label}-key-7zQ42"
                secret = f"boundary-{label}-secret-7zQ42"
                cfg = AlpacaOrderConfig(
                    api_key_id=HostileCredential(key),
                    api_secret_key=HostileCredential(secret),
                )
                original = KeyboardInterrupt(f"reflected {key} and {secret}\n" + "X" * 10_000)
                with (
                    self.subTest(boundary=label),
                    patch(target, side_effect=original),
                    self.assertRaises(KeyboardInterrupt) as raised,
                ):
                    operation(cfg)

                diagnostic = str(raised.exception)
                self.assertIs(raised.exception, original)
                self.assertNotIn(key, diagnostic)
                self.assertNotIn(secret, diagnostic)
                self.assertNotIn("\n", diagnostic)
                self.assertIn("[redacted credential]", diagnostic)
                self.assertLessEqual(len(diagnostic), 512)
                self.assertIsNone(raised.exception.__cause__)
                self.assertIsNone(raised.exception.__context__)

        self.assertEqual(HostileCredential.str_calls, 0)

    def test_configured_credentials_redact_every_equivalent_json_spelling_and_boundary(self) -> None:
        cases = (
            ('opaque"alpha123', r"opaque\u0022alpha123"),
            ("opaque§alpha123", r"opaque\u00A7alpha123"),
            ("opaque/alpha123", r"opaque\/alpha123"),
            ("opaque😀alpha123", r"opaque\uD83D\uDE00alpha123"),
        )

        for secret, reflected in cases:
            cfg = AlpacaOrderConfig(api_key_id="paper-key", api_secret_key=secret)
            with self.subTest(secret=repr(secret)):
                diagnostic = _alpaca_exception_diagnostic(
                    ValueError(f"provider reflected {reflected}"),
                    cfg=cfg,
                )
                boundary_diagnostic = _alpaca_exception_diagnostic(
                    ValueError(" " * (512 * 4 - 1) + reflected),
                    cfg=cfg,
                )

                self.assertNotIn(reflected, diagnostic)
                self.assertNotIn(reflected.split("\\", maxsplit=1)[0], diagnostic)
                self.assertIn("[redacted credential]", diagnostic)
                self.assertNotIn(reflected, boundary_diagnostic)
                self.assertIn("[redacted credential]", boundary_diagnostic)
                self.assertLessEqual(len(diagnostic), 512)
                self.assertLessEqual(len(boundary_diagnostic), 512)

