    @patch("leveraged_trader.alpaca._reconcile_alpaca_managed_positions_impl")
    def test_public_reconciliation_recursively_sanitizes_exception_groups(
        self,
        mock_reconcile_impl: Mock,
    ) -> None:
        credential = "direct-group-secret-7zQ42"
        child = FileNotFoundError(2, credential, f"/tmp/{credential}")
        BaseException.__setattr__(child, "__notes__", (f"child note {credential}",))
        child.__cause__ = ValueError(f"child cause {credential}")
        nested = ExceptionGroup(f"nested {credential}", [child])
        original = ExceptionGroup(f"outer {credential}", [nested])
        original.add_note(f"outer note {credential}")
        mock_reconcile_impl.side_effect = original

        with closing(sqlite3.connect(":memory:")) as conn, self.assertRaises(ExceptionGroup) as raised:
            reconcile_alpaca_managed_positions(
                conn,
                AlpacaOrderConfig(api_key_id="paper-key", api_secret_key=credential),
            )

        public_group = raised.exception
        public_nested = public_group.exceptions[0]
        public_child = public_nested.exceptions[0]
        rendered = "".join(traceback.format_exception(public_group))
        self.assertIsNot(public_group, original)
        self.assertIs(type(public_nested), ExceptionGroup)
        self.assertIs(type(public_child), FileNotFoundError)
        self.assertIsNone(public_child.filename)
        self.assertNotIn(credential, rendered)
        self.assertNotIn(credential, repr(public_child))
        self.assertIsNone(public_group.__cause__)
        self.assertIsNone(public_group.__context__)
        self.assertIsNone(public_child.__cause__)
        self.assertIsNone(public_child.__context__)

