    def test_direct_limit_price_formatting_ignores_ambient_decimal_context(self) -> None:
        with localcontext() as decimal_context:
            decimal_context.prec = 6
            decimal_context.rounding = ROUND_DOWN
            decimal_context.traps[Inexact] = True
            buy_price = _format_alpaca_limit_price(999_999.999, rounding=ROUND_FLOOR)
            sell_price = _format_alpaca_limit_price(999_999.999, rounding=ROUND_CEILING)

        self.assertEqual(buy_price, "999999.99")
        self.assertEqual(sell_price, "1000000")

