    @patch("leveraged_trader.alpaca.requests.get")
    def test_direct_broker_position_asset_and_order_payloads_reject_noncanonical_symbols(
        self,
        mock_get: Mock,
    ) -> None:
        client = AlpacaClient(self.cfg(buy=True, sell=True))
        mock_get.side_effect = [
            response(
                200,
                [
                    {
                        "asset_id": "asset-tqqq",
                        "symbol": "BAD\nPOSITION",
                        "asset_class": "us_equity",
                        "qty": "2",
                    }
                ],
            ),
            response(200, {"id": "asset-tqqq", "symbol": "BAD\nASSET"}),
        ]

        with self.assertRaisesRegex(ValueError, "non-canonical equity symbol"):
            client.positions()
        with self.assertRaisesRegex(ValueError, "non-canonical equity symbol"):
            client.asset("asset-tqqq")
        with self.assertRaisesRegex(ValueError, "non-canonical equity symbol"):
            _response_json(
                response(
                    200,
                    {
                        "id": "order-1",
                        "asset_id": "asset-tqqq",
                        "symbol": "BAD\nORDER",
                    },
                )
            )


